def atomic_write(path, data, mode=None, new_mode=0o600, skip_same=False):
    import os
    import secrets
    import stat
    path = os.fspath(path)
    if isinstance(data, str):
        data = data.encode("utf-8")
    folder = os.path.dirname(path) or "."
    try:
        st = os.lstat(path)
    except FileNotFoundError:
        st = None
    if st is not None and not stat.S_ISREG(st.st_mode):
        st = None
    if skip_same and st is not None:
        try:
            with open(path, "rb") as fh:
                if fh.read() == data:
                    return False
        except OSError:
            pass
    tmp = os.path.join(folder, ".%s.%s.tmp" % (os.path.basename(path), secrets.token_hex(6)))
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
    try:
        view = memoryview(data)
        while view:
            view = view[os.write(fd, view):]
        if st is not None and os.geteuid() == 0:
            os.fchown(fd, st.st_uid, st.st_gid)
        if mode is not None:
            os.fchmod(fd, mode)
        elif st is not None:
            os.fchmod(fd, stat.S_IMODE(st.st_mode))
        else:
            os.fchmod(fd, new_mode)
        os.fsync(fd)
    except BaseException:
        os.close(fd)
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise
    os.close(fd)
    try:
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise
    try:
        dfd = os.open(folder, os.O_RDONLY)
        try:
            os.fsync(dfd)
        finally:
            os.close(dfd)
    except OSError:
        pass
    return True


def http_get(url, max_bytes, timeout=20):
    import urllib.request
    if not url.startswith("https://"):
        raise ValueError("only https addresses are fetched")
    req = urllib.request.Request(url, headers={"User-Agent": "asl-dvs"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        data = resp.read(max_bytes + 1)
    if len(data) > max_bytes:
        raise ValueError("the download is larger than %d bytes" % max_bytes)
    return data


def fill_secrets(text, current, supplied=None, is_json=False):
    import json
    import re
    tag_re = re.compile(r"<redacted:[0-9a-f]{8}>")
    hdr_re = re.compile(r"^\s*\[([^\]]+)\]")
    supplied = supplied or {}
    if is_json:
        try:
            data = json.loads(text)
            cur = json.loads(current) if current is not None else None
        except ValueError:
            data = None
            cur = None
        if data is not None:
            resolved = [0]
            unresolved = []

            def walk(node, cnode, path):
                if isinstance(node, dict):
                    return {k: walk(v, cnode.get(k) if isinstance(cnode, dict) else None, path + [str(k)])
                            for k, v in node.items()}
                if isinstance(node, list):
                    return [walk(v, cnode[i] if isinstance(cnode, list) and i < len(cnode) else None,
                                 path + [str(i)]) for i, v in enumerate(node)]
                if isinstance(node, str) and tag_re.fullmatch(node):
                    if node in supplied:
                        resolved[0] += 1
                        return supplied[node]
                    if cnode is not None and not (isinstance(cnode, str) and tag_re.fullmatch(cnode)):
                        resolved[0] += 1
                        return cnode
                    unresolved.append({"line": 0, "key": ".".join(path), "tag": node})
                    return ""
                return node
            out = walk(data, cur, [])
            return json.dumps(out, indent=1, sort_keys=True) + "\n", resolved[0], unresolved
    by_sec = {}
    if current is not None:
        sec = ""
        for line in current.split("\n"):
            hm = hdr_re.match(line)
            if hm:
                sec = hm.group(1)
            by_sec.setdefault(sec, []).append(line)
    out = []
    unresolved = []
    resolved = 0
    seen = {}
    sec = ""
    for n, line in enumerate(text.split("\n"), 1):
        hm = hdr_re.match(line)
        if hm:
            sec = hm.group(1)
        body = line.lstrip()
        tags = tag_re.findall(body)
        if not tags:
            out.append(line)
            continue
        indent = line[:len(line) - len(body)]
        parts = tag_re.split(body)
        shape = tag_re.sub("\x00", body)
        k = seen.get((sec, shape), 0)
        seen[(sec, shape)] = k + 1
        got = None
        if not all(t in supplied for t in tags):
            pats = [re.escape(p).replace("\\ ", r"\s*") for p in parts]
            rx = "^" + "".join(pats[i] + ("(.*?)" if i < len(pats) - 1 else "") for i in range(len(pats))) + "$"
            try:
                pat = re.compile(rx)
            except re.error:
                pat = None
            if pat is not None:
                hits = []
                for cur_line in by_sec.get(sec, []):
                    cm = pat.match(cur_line.lstrip())
                    if cm:
                        hits.append(cm)
                if k < len(hits):
                    got = hits[k].groups()
        vals = []
        for i, t in enumerate(tags):
            if t in supplied:
                vals.append(supplied[t])
                resolved += 1
            elif got is not None:
                vals.append(got[i])
                resolved += 1
            else:
                vals.append("")
                if not body.startswith((";", "#")):
                    unresolved.append({"line": n, "key": parts[0].strip()[:40], "tag": t})
        new = indent + parts[0]
        for i, v in enumerate(vals):
            new += v + parts[i + 1]
        out.append(new)
    return "\n".join(out), resolved, unresolved


def _read_shadow_hash(account: str):
    try:
        with open("/etc/shadow", "r") as fh:
            for line in fh:
                parts = line.rstrip("\n").split(":")
                if len(parts) >= 2 and parts[0] == account:
                    return parts[1]
    except Exception as exc:
        log(f"WARNING: _read_shadow_hash: {exc}")
    return None

_libcrypt_handle = None

def _crypt_verify(password: str, stored_hash: str) -> bool:
    global _libcrypt_handle
    if _libcrypt_handle is None:
        import ctypes
        import ctypes.util
        found = None
        for name in ("libcrypt.so.1", "libcrypt.so.2", "libcrypt.so",
                     ctypes.util.find_library("crypt"), "libc.so.6"):
            if not name:
                continue
            try:
                lib = ctypes.CDLL(name)
                lib.crypt.restype  = ctypes.c_char_p
                lib.crypt.argtypes = [ctypes.c_char_p, ctypes.c_char_p]
                found = lib
                break
            except (OSError, AttributeError):
                continue
        _libcrypt_handle = found if found is not None else False
        if _libcrypt_handle is False:
            log("WARNING: _crypt_verify: no usable libcrypt found on this system")
    if _libcrypt_handle is False:
        return False
    try:
        result = _libcrypt_handle.crypt(password.encode("utf-8", "surrogateescape"),
                                         stored_hash.encode("utf-8", "surrogateescape"))
    except Exception as exc:
        log(f"WARNING: _crypt_verify: crypt(3) call failed: {exc}")
        return False
    if result is None:
        return False
    return hmac.compare_digest(result.decode("utf-8", "surrogateescape"), stored_hash)

def _verify_root_password(password: str) -> bool:
    if not password:
        return False
    try:
        import pam as _pam_mod
        return bool(_pam_mod.pam().authenticate(_AUTH_ACCOUNT, password, service="login"))
    except ImportError:
        pass
    except Exception as exc:
        log(f"WARNING: _verify_root_password: PAM check errored, trying shadow fallback: {exc}")
    try:
        stored = _read_shadow_hash(_AUTH_ACCOUNT)
        if not stored or stored[0] in ("!", "*"):
            return False
        return _crypt_verify(password, stored)
    except Exception as exc:
        log(f"WARNING: _verify_root_password: shadow fallback failed: {exc}")
        return False

_SESSION_STORE_DIR = "/run/44helper"
_SESSION_STORE_FILE = _SESSION_STORE_DIR + "/sessions.json"
_SESSION_SAVE_MIN_GAP = 60.0
_session_last_save = [0.0]

def _session_key(token: str) -> str:
    import hashlib
    return hashlib.sha256(token.encode("utf-8")).hexdigest()

def _sessions_persist(force: bool = False) -> None:
    now = time.time()
    if not force and now - _session_last_save[0] < _SESSION_SAVE_MIN_GAP:
        return
    _session_last_save[0] = now
    try:
        os.makedirs(_SESSION_STORE_DIR, mode=0o700, exist_ok=True)
        tmp = _SESSION_STORE_FILE + ".tmp"
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(_auth_sessions, f)
        os.replace(tmp, _SESSION_STORE_FILE)
    except OSError as exc:
        log(f"WARNING: could not save sessions to {_SESSION_STORE_FILE}: {exc}")

def _sessions_load() -> None:
    try:
        with open(_SESSION_STORE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (FileNotFoundError, ValueError, OSError):
        return
    with _auth_lock:
        for k, exp in (data.items() if isinstance(data, dict) else []):
            if isinstance(k, str) and isinstance(exp, (int, float)):
                _auth_sessions[k] = float(exp)
    if _auth_sessions:
        log(f"Restored {len(_auth_sessions)} login session(s) after restart")

def _issue_session() -> str:
    token = secrets.token_hex(32)
    now = time.time()
    with _auth_lock:
        _auth_sessions[_session_key(token)] = now + _SESSION_TTL_SEC
        _sessions_persist(force=True)
    return token

def _check_session(token: str) -> bool:
    if not token:
        return False
    now = time.time()
    key = _session_key(token)
    with _auth_lock:
        if key not in _auth_sessions:
            return False
        _auth_sessions[key] = now + _SESSION_TTL_SEC
        _sessions_persist()
        return True

def _revoke_all_sessions() -> int:
    with _auth_lock:
        n = len(_auth_sessions)
        _auth_sessions.clear()
        _sessions_persist(force=True)
    log(f"AUTH: logged out all devices ({n} session(s) ended)")
    return n

def _revoke_session(token: str) -> None:
    with _auth_lock:
        _auth_sessions.pop(_session_key(token), None)
        _sessions_persist(force=True)

def _login_is_locked(client_ip: str):
    now = time.time()
    with _auth_lock:
        until = _auth_locked.get(client_ip)
        if until is None:
            return None
        if now >= until:
            _auth_locked.pop(client_ip, None)
            _auth_failures.pop(client_ip, None)
            return None
        return until

def _login_record_failure(client_ip: str) -> None:
    now = time.time()
    with _auth_lock:
        hits = [t for t in _auth_failures.get(client_ip, []) if now - t < _LOGIN_WINDOW_SEC]
        hits.append(now)
        _auth_failures[client_ip] = hits
        if len(hits) >= _LOGIN_MAX_ATTEMPTS:
            _auth_locked[client_ip] = now + _LOGIN_LOCKOUT_SEC
            log(f"Auth: {client_ip} locked out for {_LOGIN_LOCKOUT_SEC}s after "
                f"{len(hits)} failed root-password attempts")

def _login_record_success(client_ip: str) -> None:
    with _auth_lock:
        _auth_failures.pop(client_ip, None)
        _auth_locked.pop(client_ip, None)

def _session_cookie_header(token: str, max_age: int) -> str:
    return f"{_SESSION_COOKIE_NAME}={token}; Path=/; HttpOnly; SameSite=Strict; Max-Age={max_age}"

def _clear_session_cookie_header() -> str:
    return f"{_SESSION_COOKIE_NAME}=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0"

def load_config() -> configparser.ConfigParser:
    cfg = configparser.ConfigParser()
    cfg.read_dict(_DEFAULT_CONFIG)

    if CONFIG_FILE.exists():
        cfg.read(CONFIG_FILE)
    else:
        try:
            CONFIG_DIR.mkdir(parents=True, exist_ok=True)
            buf = io.StringIO()
            cfg.write(buf)
            atomic_write(CONFIG_FILE, buf.getvalue(), mode=0o600)
            log(f"Created default config at {CONFIG_FILE}")
        except OSError as e:
            log(f"WARNING: could not write {CONFIG_FILE}: {e}")

    return cfg

def save_config(cfg: configparser.ConfigParser) -> None:
    try:
        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        buf = io.StringIO()
        cfg.write(buf)
        atomic_write(CONFIG_FILE, buf.getvalue(), mode=0o600)
    except OSError as e:
        log(f"WARNING: could not save {CONFIG_FILE}: {e}")

