_INSTALLED_CACHE_TTL = 20.0
_INSTALLED_CACHE: dict = {"at": 0.0, "data": None}
_INSTALLED_LOCK = threading.Lock()

def _installed_dpkg_all() -> dict[str, tuple[str, str]] | None:
    try:
        r = subprocess.run(
            ["dpkg-query", "-W", "-f=${Package}\t${db:Status-Abbrev}\t${Version}\n"],
            capture_output=True, text=True, timeout=15,
        )
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return None
    out: dict[str, tuple[str, str]] = {}
    for line in r.stdout.splitlines():
        parts = line.split("\t")
        if len(parts) >= 3 and parts[0]:
            out[parts[0].split(":")[0]] = (parts[1].strip()[:2], parts[2].strip())
    return out

def _installed_units_show(units: list[str]) -> dict[str, dict]:
    res: dict[str, dict] = {}
    if not units:
        return res
    try:
        r = subprocess.run(
            ["systemctl", "show", "-p", "Id", "-p", "LoadState", "-p", "ActiveState",
             "-p", "UnitFileState", "--"] + units,
            capture_output=True, text=True, timeout=10,
        )
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return res
    blocks = r.stdout.strip().split("\n\n")
    for unit, block in zip(units, blocks):
        kv = {}
        for line in block.splitlines():
            if "=" in line:
                k, v = line.split("=", 1)
                kv[k.strip()] = v.strip()
        res[unit] = {"load": kv.get("LoadState", "unknown"),
                     "active": kv.get("ActiveState", "unknown"),
                     "file": kv.get("UnitFileState", "")}
    return res

def _detect_installed_products(force: bool = False) -> list[dict]:
    now = time.monotonic()
    with _INSTALLED_LOCK:
        if (not force and _INSTALLED_CACHE["data"] is not None
                and now - _INSTALLED_CACHE["at"] < _INSTALLED_CACHE_TTL):
            return _INSTALLED_CACHE["data"]
    dpkg = _installed_dpkg_all()
    all_units = sorted({u for p in _INSTALLED_PRODUCTS for u in p["units"]})
    ushow = _installed_units_show(all_units)
    results: list[dict] = []
    for p in _INSTALLED_PRODUCTS:
        rx = re.compile(p["pkg_regex"])
        found_pkgs, rc_pkgs, broken_pkgs = [], [], []
        if dpkg:
            for name, (abbrev, ver) in sorted(dpkg.items()):
                if name not in p["pkgs"] and not rx.search(name):
                    continue
                st = abbrev[1:2] if len(abbrev) >= 2 else ""
                if st == "i":
                    found_pkgs.append({"name": name, "version": ver})
                elif st == "c":
                    rc_pkgs.append(name)
                elif st and st != "n":
                    broken_pkgs.append(f"{name} ({abbrev})")
        found_names = {x["name"] for x in found_pkgs}
        core_pkg_hit = [n for n in p["core_pkgs"] if n in found_names]
        core_files_hit = [f for f in p["core_files"] if os.path.exists(f)]
        units = []
        for u in p["units"]:
            info = ushow.get(u, {"load": "unknown", "active": "unknown", "file": ""})
            if info["load"] in ("not-found", "unknown") and info["file"] != "masked":
                continue
            units.append({"unit": u, "active": info["active"],
                          "masked": info["load"] == "masked" or info["file"].startswith("masked")})
        core_units_hit = [u["unit"] for u in units if u["unit"] in p["core_units"] and not u["masked"]]
        installed = bool(core_pkg_hit or core_files_hit or core_units_hit)
        notes: list[str] = []
        if broken_pkgs:
            state = "broken"
            notes.append("Half-installed package(s): " + ", ".join(broken_pkgs)
                         + " -- see Update tab, Package recovery")
        elif installed and p["expect_files"] and core_pkg_hit and not any(os.path.exists(f) for f in p["expect_files"]):
            state = "broken"
            notes.append("Package is installed but its working parts are missing -- re-run the install")
        elif installed:
            state = "installed"
        else:
            left = [x for x in p["leftover_paths"] + p["core_files"] if os.path.exists(x)]
            if rc_pkgs or left or units:
                state = "leftovers"
                if rc_pkgs:
                    notes.append("Removed, settings kept: " + ", ".join(rc_pkgs))
                if left:
                    notes.append("Left behind: " + ", ".join(left))
                if units:
                    notes.append("Unit files still present: " + ", ".join(u["unit"] for u in units))
            else:
                state = "absent"
        if installed and not core_pkg_hit and core_files_hit and p["core_pkgs"]:
            notes.append("Found by file (" + ", ".join(core_files_hit) + "), not from the apt package")
        if p["key"] == "amp" and installed:
            parts = []
            if os.path.exists("/usr/bin/amp-server") or any(u["unit"] == "amp-server.service" for u in units):
                parts.append("amp-server")
            if os.path.exists("/usr/etc/amp-hub.env") or any(u["unit"] == "amp-hub.service" for u in units):
                parts.append("amp-hub")
            if parts:
                notes.append("Parts: " + ", ".join(parts))
        masked = [u["unit"] for u in units if u["masked"]]
        if masked:
            notes.append("Masked: " + ", ".join(masked))
        version = ""
        for n in p["core_pkgs"]:
            for x in found_pkgs:
                if x["name"] == n:
                    version = x["version"]
                    break
            if version:
                break
        results.append({
            "key": p["key"], "name": p["name"], "tab": p["tab"], "state": state,
            "version": version,
            "running": [u["unit"] for u in units if u["active"] == "active"],
            "stopped": [u["unit"] for u in units if u["active"] != "active" and not u["masked"]],
            "notes": notes,
            "dpkg_ok": dpkg is not None,
        })
    with _INSTALLED_LOCK:
        _INSTALLED_CACHE["at"] = time.monotonic()
        _INSTALLED_CACHE["data"] = results
    return results

def build_overview_data(cfg: configparser.ConfigParser) -> dict:
    my_port = cfg.getint("server", "port", fallback=9997)

    wg0_present = _wg0_interface_present()
    wg0_conf = _parse_wg0_conf()
    wg0_perms_ok = _wg0_conf_perms_ok()
    wg_status = _wg_show_wg0()
    fw_zone = _firewalld_zone_info_cached()
    tunnel_names = _configured_tunnel_names(cfg)

    self_check = _run_self_check(my_port, fw_zone, wg0_perms_ok)
    installed = _detect_installed_products()

    return {
        "installed": installed,
        "wg0_present": wg0_present,
        "wg0_conf": wg0_conf,
        "wg0_conf_perms_ok": wg0_perms_ok,
        "wg_status": wg_status,
        "firewalld_zone": fw_zone,
        "tunnel_names": tunnel_names,
        "self_check": self_check,
        "tunnel_kind": cfg.get("tunnels", "tunnel.pi.kind", fallback=""),
        "asl_reg": asl_registration_info() if shutil.which("asterisk") else None,
        "checked_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }

def _run_self_check(my_port: int, fw_zone: dict | None, wg0_perms_ok: bool | None) -> list[dict]:
    findings: list[dict] = []

    if fw_zone is None:
        findings.append({
            "level": "info",
            "msg": (
                f"{FIREWALLD_ZONE} firewall zone not found yet — nothing to "
                "audit. Expected before the Full or Split Tunnel tab's steps 2 to 6 have run."
            ),
        })
    else:
        exposed_ports = set(fw_zone.get("ports", []))
        exposed_services = set(fw_zone.get("services", []))

        _svc_ports = {"cockpit": 9090}

        def _port_exposed(port: int) -> bool:
            for p in exposed_ports:
                lo, _, hi = p.split("/")[0].partition("-")
                if lo.isdigit() and int(lo) <= port <= int(hi if hi.isdigit() else lo):
                    return True
            return any(_svc_ports.get(svc) == port for svc in exposed_services)

        if _port_exposed(my_port):
            findings.append({
                "level": "danger",
                "msg": (
                    f"44helper's own dashboard port ({my_port}) appears "
                    f"exposed in the {FIREWALLD_ZONE} zone. This dashboard "
                    "should never be reachable on the public 44Net address."
                ),
            })

        for port, label in _WATCHED_DASHBOARD_PORTS.items():
            if _port_exposed(port):
                findings.append({
                    "level": "danger",
                    "msg": f"{label} port ({port}) appears exposed in the {FIREWALLD_ZONE} zone.",
                })

        if _port_exposed(_WATCHED_AMI_PORT) or "astmgr" in exposed_services:
            findings.append({
                "level": "danger",
                "msg": (
                    f"Asterisk AMI ({_WATCHED_AMI_PORT}) appears exposed in the "
                    f"{FIREWALLD_ZONE} zone — the 44Net Connect manual flags "
                    "this as especially risky (§1)."
                ),
            })

        if not findings:
            findings.append({"level": "ok", "msg": f"No watched ports found exposed in the {FIREWALLD_ZONE} zone."})

    if wg0_perms_ok is None:
        pass
    elif wg0_perms_ok is False:
        findings.append({
            "level": "warn",
            "msg": f"{WG0_CONF_PATH} is not mode 600 — private key file permissions have drifted.",
        })
    else:
        findings.append({"level": "ok", "msg": f"{WG0_CONF_PATH} permissions OK (600)."})

    findings += _ov_endpoint_findings_cached()
    findings += _ov_health_findings()
    return findings

_OV_EP_CACHE: dict = {"at": 0.0, "data": []}

def _ov_endpoint_findings_cached(force: bool = False) -> list[dict]:
    if force or time.time() - _OV_EP_CACHE["at"] >= _OV_HEALTH_TTL:
        _OV_EP_CACHE.update(data=_ov_endpoint_findings(), at=time.time())
    return list(_OV_EP_CACHE["data"])

def _wg_pin_outdated() -> bool:
    try:
        with open(WG0_CONF_PATH, "r") as f:
            text = f.read()
    except OSError:
        return False
    return bool(_wg_apply_endpoint_pin(text)[1])

def _ov_endpoint_findings() -> list[dict]:
    findings: list[dict] = []
    try:
        with open(WG0_CONF_PATH, "r") as f:
            ep = _wg_endpoint_info(f.read())
    except OSError:
        ep = None
    if ep and ep["needed"] and _wg_endpoint_loop_live(ep["ip"]):
        findings.append({
            "id": "endpoint", "fix": ["endpoint_pin"],
            "level": "danger",
            "msg": (f"The tunnel server ({ep['host']}) is a 44Net address inside AllowedIPs and routes back into wg0: "
                    "a routing loop, so the tunnel can't reach it (the 44Net Connect dashboard shows idle). "
                    "Fix it on the Split Tunnel tab, step 4b."),
        })
    elif ep and ep["needed"] and not ep["pinned"]:
        findings.append({
            "id": "endpoint", "fix": ["endpoint_pin"],
            "level": "warn",
            "msg": (f"The tunnel server ({ep['host']}) is inside AllowedIPs and wg0.conf has no endpoint pin. "
                    "The next tunnel start will loop. Fix it on the Split Tunnel tab, step 4b."),
        })
    elif ep and ep["needed"] and _wg_pin_outdated():
        findings.append({
            "id": "endpoint", "fix": ["endpoint_pin"],
            "level": "warn",
            "msg": ("wg0.conf has an older endpoint pin that gives up silently when the tunnel starts before the "
                    "normal default route exists (at boot), so the tunnel comes up in a routing loop with no "
                    "handshake. Update it: the new pin waits up to 30 s for the route, and otherwise fails the "
                    "start so it is retried."),
        })
    return findings

_OV_HANDSHAKE_MAX = 180
_OV_DVS_UNITS = ("analog_bridge.service", "Analog_Bridge.service", "mmdvm_bridge.service", "MMDVM_Bridge.service",
                 "md380-emu.service", "stfu.service", "STFU.service", "ysfgateway.service", "ysfparrot.service", "p25gateway.service", "nxdngateway.service",
                 "ircddbgatewayd.service", "webproxy.service")

def _ov_q(argv: list[str], timeout: int = 6) -> tuple[int, str]:
    try:
        r = subprocess.run(argv, capture_output=True, text=True, timeout=_fw_timeout(argv, timeout))
    except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
        return -1, ""
    return r.returncode, r.stdout or ""

def _ov_handshake_finding(text: str | None) -> dict | None:
    if text is None or not _wg0_interface_present():
        return None
    rc, out = _ov_q(["wg", "show", "wg0", "latest-handshakes"])
    if rc != 0:
        return None
    stamps = [int(t) for t in out.split() if t.isdigit()]
    parsed = _parse_wg_conf_text(text, mask_private_key=True)
    keepalive = bool(parsed["peers"]) and not _wg_keepalive_off(_wg_conf_field(parsed["peers"][0], "PersistentKeepalive"))
    if not stamps or max(stamps) == 0:
        return {"id": "handshake", "fix": [] if keepalive else ["keepalive"],
                "level": "danger" if keepalive else "warn",
                "msg": ("wg0 is up but has never completed a handshake with the 44Net server, so the tunnel carries nothing "
                        "(the 44Net Connect dashboard shows idle). Check the key and Endpoint, and that the tunnel server "
                        "doesn't route into wg0 (ip -4 route get <endpoint>).")}
    age = int(time.time() - max(stamps))
    if age <= _OV_HANDSHAKE_MAX:
        return {"id": "handshake", "fix": [], "level": "ok", "msg": "Tunnel handshake is recent (under 3 minutes)."}
    nice = f"{age // 3600} h {age % 3600 // 60} min" if age >= 3600 else f"{age // 60} min"
    if keepalive:
        return {"id": "handshake", "fix": [], "level": "danger",
                "msg": (f"Last tunnel handshake {nice} ago, although a keepalive is set: the tunnel isn't reaching the 44Net "
                        "server (the dashboard shows idle). Check ip -4 route get <endpoint> doesn't say wg0, and the key "
                        "and Endpoint.")}
    return {"id": "handshake", "fix": ["keepalive"], "level": "warn",
            "msg": (f"Last tunnel handshake {nice} ago. With no PersistentKeepalive a quiet tunnel goes idle, and stations "
                    "on 44Net can't reach this node until it sends something. Add PersistentKeepalive = 25 under [Peer].")}

def _ov_unit_states(units) -> dict[str, dict]:
    rc, out = _ov_q(["systemctl", "show", "-p", "Id,LoadState,ActiveState,UnitFileState,Result", "--"] + list(units), 8)
    states: dict[str, dict] = {}
    if rc != 0:
        return states
    for block in out.strip().split("\n\n"):
        kv = dict(ln.split("=", 1) for ln in block.splitlines() if "=" in ln)
        if kv.get("Id"):
            states[kv["Id"]] = kv
    return states

def _ov_failed_findings() -> list[dict]:
    rc, out = _ov_q(["systemctl", "--failed", "--no-legend", "--plain", "--type=service"], 8)
    failed = [ln.split()[0] for ln in out.splitlines() if ln.split() and ln.split()[0].endswith(".service")] if rc == 0 else []
    states = _ov_unit_states(_OV_DVS_UNITS)
    stopped = [u for u, st in states.items()
               if st.get("LoadState") == "loaded" and st.get("UnitFileState") == "enabled"
               and st.get("ActiveState") in ("inactive", "failed") and u not in failed]
    findings: list[dict] = []
    if "netcheck.service" in failed and stopped:
        names = " ".join(u.replace(".service", "") for u in stopped)
        findings.append({"id": "netcheck", "fix": ["netcheck_fixes", "start_services"], "level": "danger",
                         "msg": (f"netcheck failed, so these DVSwitch services never started: {names}. Apply the netcheck "
                                 "fixes first (while netcheck still fails, a service that requires it won't start), then "
                                 f"start them: sudo systemctl start {names}.")})
        stopped = []
    if failed:
        findings.append({"id": "failed", "fix": [], "level": "danger",
                         "msg": "Failed services: " + ", ".join(u.replace(".service", "") for u in failed)
                                + ". See journalctl -u <name> -b for why."})
    if stopped:
        findings.append({"id": "stopped", "fix": ["netcheck_fixes", "start_services"], "level": "warn",
                         "msg": "Enabled at boot but not running: " + ", ".join(u.replace(".service", "") for u in stopped) + "."})
    return findings

def _ov_dns_finding(text: str | None) -> dict | None:
    if not text:
        return None
    if _wg_legacy_fix(text)[1]:
        return {"id": "dns_predown", "fix": ["dns_predown"], "level": "warn",
                "msg": ("wg0.conf's line that undoes the tunnel DNS can stop the tunnel's shutdown: in a PostDown line it runs "
                        "after wg0 is gone and fails, and a PreDown line without '|| true' fails when systemd-resolved doesn't "
                        "answer. wg-quick then stops there, wg0 stays up and the next start fails. Fix the line.")}
    need = _wg_conf_dns_need(text)
    if not need:
        return None
    if "no resolvconf" in need:
        return {"id": "dns", "fix": ["dns_off"], "level": "danger",
                "msg": f"wg0.conf {need}: the next tunnel start will fail. Set the DNS card (step 4a) to Off."}
    ok, why = _wg_resolved_answers()
    if ok:
        return None
    return {"id": "dns", "fix": ["restart_resolved", "dns_off"], "level": "danger",
            "msg": (f"wg0.conf {need}, which goes through systemd-resolved, and resolved isn't answering ({why}). The next "
                    "tunnel start will wait 25 s and fail. Run sudo systemctl restart systemd-resolved (or reboot), or set "
                    "the DNS card (step 4a) to Off.")}

def _ov_address_finding(text: str | None) -> dict | None:
    if not text:
        return None
    parsed = _parse_wg_conf_text(text, mask_private_key=True)
    wide = []
    for part in _wg_conf_field(parsed["interface"], "Address").split(","):
        try:
            iface = ipaddress.ip_interface(part.strip())
        except ValueError:
            continue
        if iface.version == 4 and iface.network.prefixlen != 32:
            wide.append(str(iface))
    if not wide:
        return None
    return {"id": "address", "fix": ["address32"] if _hl_address32_target(text) else [], "level": "warn",
            "msg": (f"wg0.conf Address is {', '.join(wide)}, not a single /32. A 44Net Connect tunnel is one address, and a "
                    f"wider prefix routes the whole {', '.join(str(ipaddress.ip_interface(w).network) for w in wide)} into wg0. "
                    "Check it against the portal and change it to /32 unless you were given a subnet.")}

_OV_HEALTH_TTL = 30.0
_OV_HEALTH_CACHE: dict = {"at": 0.0, "data": []}

def _ov_health_findings(force: bool = False) -> list[dict]:
    now = time.time()
    if not force and now - _OV_HEALTH_CACHE["at"] < _OV_HEALTH_TTL:
        return list(_OV_HEALTH_CACHE["data"])
    data = _ov_health_compute()
    _OV_HEALTH_CACHE.update(at=time.time(), data=data)
    return list(data)

def _ov_boot_finding(text: str | None) -> dict | None:
    if not text:
        return None
    st = status_boot_order()
    if st["done"]:
        if st.get("last_boot_now") and ": not ready" in st.get("last_boot", ""):
            return {"id": "boot_late", "fix": [], "level": "warn",
                    "msg": "At this boot the network, the tunnel or DNS wasn't ready in time: " + st["last_boot"].split(": ", 1)[-1]
                           + ". A follow-up restarts the DVSwitch services once it is; see journalctl -b -u 44helper-netready."}
        return None
    if st["wg_enabled"] not in ("enabled", "enabled-runtime"):
        return {"id": "boot_order", "fix": ["boot_order"], "level": "danger",
                "msg": "The tunnel isn't enabled at boot, so it stays down after a reboot. Set the boot order to enable it "
                       "and make DVSwitch wait for it."}
    return {"id": "boot_order", "fix": ["boot_order"], "level": "warn",
            "msg": ("After a reboot the tunnel or the DVSwitch services may come up in the wrong order (missing: "
                    + "; ".join(st["missing"]) + "). Set the boot order so DVSwitch waits for the network, the tunnel "
                    "and DNS, and the tunnel retries if its first start fails.")}

_AST_IAX_CONF = "/etc/asterisk/iax.conf"
_BOOT_NONLOCAL_PATH = "/etc/sysctl.d/90-44helper-nonlocal-bind.conf"
_BOOT_NONLOCAL_TEXT = "net.ipv4.ip_nonlocal_bind = 1\n"

def _ast_iax_bindaddrs() -> list[str]:
    out: list[str] = []
    seen: set = set()

    def read(path: str, section: str, depth: int) -> str:
        if depth > 3 or path in seen:
            return section
        seen.add(path)
        try:
            with open(path, "r", errors="replace") as f:
                lines = f.read().splitlines()
        except OSError:
            return section
        for raw in lines:
            st = raw.split(";", 1)[0].strip()
            m = re.match(r'^#(?:try)?include\s+"?([^"]+?)"?$', st)
            if m:
                inc = m.group(1).strip()
                section = read(inc if inc.startswith("/") else os.path.join("/etc/asterisk", inc), section, depth + 1)
                continue
            if st.startswith("["):
                section = st[1:].split("]", 1)[0].strip().lower()
                continue
            if section == "general":
                m = re.match(r"^bindaddr\s*=>?\s*\[?([0-9A-Fa-f.:]+?)\]?(?::\d+)?$", st, re.I)
                if m:
                    out.append(m.group(1))
        return section

    read(_AST_IAX_CONF, "", 0)
    return out

def _wg0_conf_addresses(text: str | None) -> list[str]:
    out = []
    for m in re.finditer(r"(?im)^\s*Address\s*=\s*(.+)$", text or ""):
        for part in m.group(1).split(","):
            out.append(part.strip().split("/", 1)[0])
    return out

def _ast_tunnel_binds(text: str | None) -> list[str]:
    addrs = _wg0_conf_addresses(text)
    out = []
    for a in _ast_iax_bindaddrs():
        try:
            ip = ipaddress.ip_address(a)
        except ValueError:
            continue
        if ip.is_unspecified or ip.is_loopback:
            continue
        if a in addrs or (ip.version == 4 and ip in ipaddress.ip_network("44.0.0.0/8")):
            out.append(a)
    return out

def _ov_ast_bind_finding(text: str | None) -> dict | None:
    if not text:
        return None
    binds = _ast_tunnel_binds(text)
    if not binds:
        return None
    full = "0.0.0.0/0" in re.sub(r"\s", "", text)
    ready = _boot_file_is(_BOOT_NONLOCAL_PATH, _BOOT_NONLOCAL_TEXT)
    msg = f"Asterisk's iax.conf binds IAX to the tunnel address {', '.join(binds)}. "
    if not full:
        msg += ("On a split tunnel use bindaddr=0.0.0.0: IAX to nodes outside 44Net then leaves through your router with a "
                "44 source address and can fail, while 0.0.0.0 already uses the 44 address for 44Net nodes. ")
    msg += ("At boot Asterisk starts before wg0 has that address, so the bind fails until Asterisk restarts"
            + ("; Set the boot order lets it bind before the tunnel is up (net.ipv4.ip_nonlocal_bind)." if not ready else
               "; the boot order already lets it bind early (net.ipv4.ip_nonlocal_bind)."))
    return {"id": "ast_bind", "fix": [] if ready else ["boot_order"], "level": "warn", "msg": msg}

def _ov_health_compute() -> list[dict]:
    try:
        with open(WG0_CONF_PATH, "r") as f:
            text = f.read()
    except OSError:
        text = None
    out: list[dict] = []
    for fn in (lambda: _ov_handshake_finding(text), lambda: _ov_dns_finding(text), lambda: _ov_address_finding(text),
               lambda: _ov_boot_finding(text), lambda: _ov_ast_bind_finding(text)):
        try:
            r = fn()
        except Exception as exc:
            log(f"overview check failed: {exc}")
            r = None
        if r:
            out.append(r)
    try:
        out += _ov_failed_findings()
    except Exception as exc:
        log(f"overview check failed: {exc}")
    return out

def _hl_stopped_units() -> list[str]:
    states = _ov_unit_states(_OV_DVS_UNITS)
    return [u for u in _OV_DVS_UNITS if u in states
            and states[u].get("LoadState") == "loaded" and states[u].get("UnitFileState") == "enabled"
            and states[u].get("ActiveState") in ("inactive", "failed")]

def _hl_address32_target(text: str | None) -> str:
    if not text:
        return ""
    parsed = _parse_wg_conf_text(text, mask_private_key=True)
    hits = []
    for part in _wg_conf_field(parsed["interface"], "Address").split(","):
        try:
            iface = ipaddress.ip_interface(part.strip())
        except ValueError:
            continue
        if iface.version == 4 and iface.network.prefixlen != 32 and _half_in_44net(str(iface.ip)):
            hits.append(part.strip())
    return hits[0] if len(hits) == 1 else ""

def _hl_testing_refusal() -> dict | None:
    if _half_mode() == "testing":
        return {"success": False, "verified": False,
                "output": "Refused: a half-tunnel test is running. Use Undo now or Make permanent on its card first."}
    if _fx_mode() == "testing":
        return {"success": False, "verified": False,
                "output": "Refused: a full-tunnel-exceptions test is running. Use Undo now or Make permanent on its card first."}
    return None

def _hl_read_conf() -> str | None:
    try:
        with open(WG0_CONF_PATH, "r", newline="") as f:
            return f.read()
    except OSError:
        return None

def _hl_done(res: dict) -> dict:
    _OV_HEALTH_CACHE["at"] = 0.0
    _OV_EP_CACHE["at"] = 0.0
    _RS_ANSWER_CACHE["at"] = 0.0
    return res

def action_health_start_services() -> dict:
    err = _require_root()
    if err:
        return err
    units = _hl_stopped_units()
    if not units:
        return _hl_done({"success": True, "verified": True, "output": "Every enabled DVSwitch service is already running."})
    out, ok = [], True
    for u in units:
        r = _run_argv(["systemctl", "start", u], timeout=60)
        active = _systemctl_is_active(u)
        out.append(("ok    " if active else "FAIL  ") + u.replace(".service", "") + (" started" if active else " did not start"))
        if not active:
            ok = False
            if r["output"]:
                out.append("      " + r["output"].splitlines()[-1])
            try:
                j = subprocess.run(["journalctl", "-u", u, "-b", "-n", "8", "--no-pager", "-o", "cat"],
                                   capture_output=True, text=True, timeout=8).stdout.strip()
            except (FileNotFoundError, subprocess.TimeoutExpired):
                j = ""
            out += ["      " + ln for ln in j.splitlines()]
    if not ok:
        out.append("Some services didn't start; their last log lines are above. If netcheck failed, use Apply netcheck fixes.")
    return _hl_done({"success": ok, "verified": ok, "output": "\n".join(out)})

def action_health_netcheck_fixes() -> dict:
    err = _require_root()
    if err:
        return err
    sc = scan_netcheck()
    if not sc.get("available") or not sc.get("netcheck", {}).get("exists"):
        return _hl_done({"success": True, "verified": True, "output": "netcheck.service isn't on this node, so there is nothing to fix."})
    fx = sc["fixes"]
    out, ok, did = [], True, False
    if fx["unit_fix"]["applicable"] and not fx["unit_fix"]["applied"]:
        r = action_netcheck_fix_unit()
        did = True
        good = bool(r.get("success") and r.get("verified"))
        ok = ok and good
        out.append(("ok    " if good else "FAIL  ") + "netcheck: runs once, after the network is online"
                   + ("" if good else ": " + r.get("output", "").strip().splitlines()[-1] if r.get("output", "").strip() else ""))
    req = _boot_netcheck_required_by(_boot_dv_units())
    if req:
        r = action_netcheck_nonfatal()
        did = True
        good = bool(r.get("success") and r.get("verified"))
        ok = ok and good
        out.append(("ok    " if good else "FAIL  ") + "a failed netcheck no longer stops "
                   + ", ".join(u.replace(".service", "") for u in req)
                   + ("" if good else ": " + r.get("output", "").strip().replace("\n", " ")))
    if fx["waitonline_fix"]["applicable"]:
        r = action_netcheck_enable_waitonline()
        did = True
        ok = ok and bool(r.get("success") and r.get("verified"))
        out.append(("ok    " if r.get("success") else "FAIL  ") + f"{fx['waitonline_fix']['unit']} enabled")
    if not did:
        out.append("The recommended netcheck fixes are already in place.")
    if fx["target_fix"]["applicable"]:
        out.append(f"netcheck probes {fx['target_fix']['current'] or '?'}; change it on the netcheck card under step 6 if that "
                   "target can't be reached at boot.")
    out.append("Revert is on the netcheck card under step 6.")
    return _hl_done({"success": ok, "verified": ok, "output": "\n".join(out)})

def _wg_strip_saveconfig(text: str) -> tuple[str, bool]:
    section, kept, removed = "", [], False
    for raw in text.splitlines(keepends=True):
        st = raw.split("#", 1)[0].strip()
        if st.startswith("["):
            section = st.lower()
        if section == "[interface]" and re.match(r"^saveconfig\s*=\s*true$", st, re.I):
            removed = True
            continue
        kept.append(raw)
    return ("".join(kept), True) if removed else (text, False)

def _wg_set_address32(text: str, target: str) -> str | None:
    new_addr = str(ipaddress.ip_interface(target).ip) + "/32"
    lines = text.splitlines(keepends=True)
    section = ""
    for i, raw in enumerate(lines):
        body = raw.rstrip("\r\n")
        low = body.strip().lower()
        if low.startswith("["):
            section = low
            continue
        if section == "[interface]" and re.match(r"^\s*address\s*=", body, re.I) and target in body:
            lines[i] = body.replace(target, new_addr, 1) + raw[len(body):]
            return "".join(lines)
    return None

def _wg_add_keepalive(text: str) -> str | None:
    lines = text.splitlines(keepends=True)
    section, peers = "", 0
    for i, raw in enumerate(lines):
        body = raw.rstrip("\r\n")
        low = body.strip().lower()
        if low.startswith("["):
            section = low
            peers += low == "[peer]"
            continue
        if section == "[peer]" and peers == 1 and re.match(r"^\s*persistentkeepalive\s*=", body, re.I):
            lines[i] = re.match(r"^\s*", body).group(0) + "PersistentKeepalive = 25" + raw[len(body):]
            return "".join(lines)
    nl = "\r\n" if "\r\n" in text else "\n"
    out_lines, in_peer, inserted = [], False, False
    for raw in text.splitlines(keepends=True):
        low = raw.strip().lower()
        if low.startswith("[") and in_peer and not inserted:
            blanks = []
            while out_lines and not out_lines[-1].strip():
                blanks.append(out_lines.pop())
            out_lines.append("PersistentKeepalive = 25" + nl)
            out_lines += blanks
            inserted = True
        if low == "[peer]":
            in_peer = True
        out_lines.append(raw)
    if not in_peer:
        return None
    if not inserted:
        if out_lines and not out_lines[-1].endswith(("\n", "\r")):
            out_lines[-1] += nl
        out_lines.append("PersistentKeepalive = 25" + nl)
    return "".join(out_lines)

def _wg_drop_dns_lines(text: str, hooks: bool = False) -> tuple[str, list[str]]:
    section, kept, removed = "", [], []
    for raw in text.splitlines(keepends=True):
        st = raw.split("#", 1)[0].strip()
        if st.startswith("["):
            section = st.lower()
        if section == "[interface]" and (re.match(r"^dns\s*=", st, re.I) or (
                hooks and re.match(r"^(pre|post)(up|down)\s*=.*\bresolvectl\b", st, re.I))):
            removed.append(raw.strip())
            continue
        kept.append(raw)
    return "".join(kept), removed

def _wg_drop_iface_key(text: str, key: str) -> tuple[str, list[str]]:
    section, kept, removed = "", [], []
    for raw in text.splitlines(keepends=True):
        st = raw.split("#", 1)[0].strip()
        if st.startswith("["):
            section = st.lower()
        if section == "[interface]" and re.match(r"^" + re.escape(key) + r"\s*=", st, re.I):
            removed.append(raw.strip())
            continue
        kept.append(raw)
    return "".join(kept), removed

def _wg_set_allowed_ips(text: str, value: str) -> str | None:
    lines = text.splitlines(keepends=True)
    section, peers = "", 0
    for i, raw in enumerate(lines):
        body = raw.rstrip("\r\n")
        low = body.strip().lower()
        if low.startswith("["):
            section = low
            if low == "[peer]":
                peers += 1
            continue
        if section == "[peer]" and peers == 1 and re.match(r"^\s*allowedips\s*=", body, re.I):
            lines[i] = re.match(r"^\s*", body).group(0) + "AllowedIPs = " + value + raw[len(body):]
            return "".join(lines)
    return None

_PI_TAB_ALLOWED_IPS = {"split": "44.0.0.0/9, 44.128.0.0/10", "full": "0.0.0.0/0"}

def _wg_normalize(text: str, kind: str, opts: dict | None = None) -> dict:
    opts = opts or {}
    changes: list[str] = []
    fixed: list[str] = []
    choices: list[dict] = []
    blocker = ""
    mismatch = None
    text, sc = _wg_strip_saveconfig(text)
    if sc:
        fixed.append("SaveConfig = true removed: wg-quick would rewrite wg0.conf on every stop and drop 44helper's settings.")
    if re.search(r"^\s*dns\s*=", text, re.I | re.M):
        need = _wg_conf_dns_need(text)
        if need:
            ok, why = (False, "") if "no resolvconf" in need else _wg_resolved_answers()
            if not ok:
                text, removed = _wg_drop_dns_lines(text)
                cause = (f"systemd-resolved isn't answering ({why})" if why else
                         "there is no resolvconf command, which a DNS = line needs")
                fixed.append(f"DNS line removed ({', '.join(removed)}): {cause}, so "
                             "the tunnel would fail to start. DNS is now Off; set it on the DNS card (4a) once step 1a "
                             "is green.")
    target = _hl_address32_target(text)
    if target:
        new_addr = str(ipaddress.ip_interface(target).ip) + "/32"
        on = bool(opts.get("address32", True))
        choices.append({"id": "address32", "on": on, "label": f"Change Address {target} to {new_addr}",
                        "detail": "A 44Net Connect tunnel is one address. Check the portal first: untick this only "
                                  "if ARDC gave you a subnet."})
        if on:
            new = _wg_set_address32(text, target)
            if new is not None:
                text = new
                changes.append(f"Address {target} changed to {new_addr}.")
    parsed = _parse_wg_conf_text(text, mask_private_key=True)
    if parsed["peers"] and _wg_keepalive_off(_wg_conf_field(parsed["peers"][0], "PersistentKeepalive")):
        on = bool(opts.get("keepalive", True))
        choices.append({"id": "keepalive", "on": on, "label": "Add PersistentKeepalive = 25 under [Peer]",
                        "detail": "Without it a quiet tunnel goes idle and stations on 44Net can't reach this node "
                                  "until it sends something."})
        if on:
            new = _wg_add_keepalive(text)
            if new is not None:
                text = new
                changes.append("PersistentKeepalive = 25 added under [Peer].")
    if kind in _PI_TAB_ALLOWED_IPS and _pi_allowed_ips_mismatch_note(text, kind):
        want = _PI_TAB_ALLOWED_IPS[kind]
        other = "Full Tunnel" if kind == "split" else "Split Tunnel"
        cur = _wg_conf_field(_parse_wg_conf_text(text, mask_private_key=True)["peers"][0], "AllowedIPs")
        mismatch = {"current": cur, "want": want, "other_tab": other}
        if opts.get("allowed") == "rewrite":
            new = _wg_set_allowed_ips(text, want)
            if new is not None:
                text = new
                changes.append(f"AllowedIPs changed from {cur} to {want} for this tab.")
        else:
            blocker = (f"AllowedIPs is {cur}, which doesn't fit this tab ({want}). Choose to rewrite it, or paste the "
                       f"config on the {other} tab instead.")
    raw_servers = []
    for m in re.finditer(r"(?im)^\s*dns\s*=\s*(.+)$", text):
        raw_servers += [x.strip() for x in m.group(1).split(",") if x.strip()]
    if raw_servers:
        outside = _wg_dns_outside_tunnel(text, raw_servers)
        if outside:
            text, removed = _wg_drop_dns_lines(text)
            fixed.append(f"DNS line removed ({', '.join(removed)}): {', '.join(outside)} isn't inside this tunnel's "
                         "AllowedIPs, so lookups sent to it over wg0 would be dropped and names would stop resolving. "
                         "Set 44Net DNS on the DNS card (4a) if you want it.")
    text, rt_note = _wg_apply_split_routing(text)
    if rt_note:
        fixed.append(rt_note)
    pinned, pin_note = _wg_apply_endpoint_pin(text)
    if pin_note:
        fixed.append(pin_note)
    return {"text": pinned, "changes": fixed + changes, "fixed": fixed, "choices": choices, "mismatch": mismatch,
            "blocker": blocker}

def action_paste_preview(config_text: str, kind: str = "", opts: dict | None = None) -> dict:
    valid, msg = _validate_wg_config_text(config_text)
    if not valid:
        return {"success": False, "valid": False, "output": f"Rejected: {msg}"}
    n = _wg_normalize(config_text, kind, opts)
    return {"success": True, "valid": True, "fixed": n["fixed"], "choices": n["choices"],
            "mismatch": n["mismatch"], "blocker": n["blocker"], "output": ""}

def action_health_address32() -> dict:
    err = _require_root() or _hl_testing_refusal()
    if err:
        return err
    text = _hl_read_conf()
    target = _hl_address32_target(text)
    if not target:
        return _hl_done({"success": False, "verified": False,
                         "output": "Nothing to change: wg0.conf doesn't have exactly one 44Net address wider than /32."})
    new_addr = str(ipaddress.ip_interface(target).ip) + "/32"
    new = _wg_set_address32(text, target)
    if new is None:
        return _hl_done({"success": False, "verified": False, "output": "Couldn't find the Address line to change."})
    try:
        out = _wg_write_conf(new)
    except OSError as e:
        return _hl_done({"success": False, "verified": False, "output": f"Write failed: {e}"})
    out.append(f"Address {target} changed to {new_addr}. The running tunnel still uses the old prefix until it restarts: "
               "press Restart tunnel when you're on the LAN.")
    return _hl_done({"success": True, "verified": True, "output": "\n".join(out)})

def action_health_keepalive() -> dict:
    err = _require_root() or _hl_testing_refusal()
    if err:
        return err
    text = _hl_read_conf()
    if text is None:
        return {"success": False, "verified": False, "output": "No wg0.conf."}
    parsed = _parse_wg_conf_text(text, mask_private_key=True)
    if not parsed["peers"]:
        return {"success": False, "verified": False, "output": "wg0.conf has no [Peer] section."}
    if not _wg_keepalive_off(_wg_conf_field(parsed["peers"][0], "PersistentKeepalive")):
        return _hl_done({"success": True, "verified": True, "output": "A PersistentKeepalive is already set."})
    pub = _wg_conf_field(parsed["peers"][0], "PublicKey")
    new = _wg_add_keepalive(text)
    if new is None:
        return {"success": False, "verified": False, "output": "wg0.conf has no [Peer] section."}
    try:
        out = _wg_write_conf(new)
    except OSError as e:
        return {"success": False, "verified": False, "output": f"Write failed: {e}"}
    if _wg0_interface_present() and pub:
        r = _run_argv(["wg", "set", "wg0", "peer", pub, "persistent-keepalive", "25"])
        out.append(("ok    " if r["success"] else "FAIL  ") + "applied to the running tunnel" + ("" if r["success"] else ": " + r["output"]))
    out.append("PersistentKeepalive = 25 added under [Peer]: the Pi now checks in every 25 s.")
    return _hl_done({"success": True, "verified": True, "output": "\n".join(out)})

def action_health_restart_resolved() -> dict:
    err = _require_root()
    if err:
        return err
    r = _run_argv(["systemctl", "restart", "systemd-resolved"], timeout=30)
    ok, why = _wg_resolved_answers()
    msg = (r["output"] + "\n" if r["output"] else "") + ("ok    systemd-resolved answers." if ok else
           f"FAIL  systemd-resolved still isn't answering ({why}). Reboot the Pi, or use Set DNS to Off.")
    return _hl_done({"success": ok, "verified": ok, "output": msg})

def action_health_dns_off() -> dict:
    err = _require_root() or _hl_testing_refusal()
    if err:
        return err
    text = _hl_read_conf()
    if text is None:
        return {"success": False, "verified": False, "output": "No wg0.conf."}
    text2 = _wg_block_remove(text, _WG_DNS_BEGIN, _WG_DNS_END) if any(
        ln.strip() == _WG_DNS_BEGIN for ln in text.splitlines()) else text
    new, removed = _wg_drop_dns_lines(text2, hooks=True)
    if new == text:
        return _hl_done({"success": True, "verified": True, "output": "wg0.conf has no DNS setting; nothing to change."})
    try:
        out = _wg_write_conf(new)
    except OSError as e:
        return {"success": False, "verified": False, "output": f"Write failed: {e}"}
    out += ["removed: " + ln for ln in removed]
    out.append("DNS setting taken out of wg0.conf; the Pi keeps its own resolver. Restart the tunnel for it to take effect.")
    return _hl_done({"success": True, "verified": True, "output": "\n".join(out)})

def action_health_dns_predown() -> dict:
    err = _require_root() or _hl_testing_refusal()
    if err:
        return err
    text = _hl_read_conf()
    if text is None:
        return {"success": False, "verified": False, "output": "No wg0.conf."}
    if not _wg_legacy_fix(text)[1]:
        return _hl_done({"success": True, "verified": True, "output": "Already a PreDown line with '|| true'; nothing to change."})
    try:
        out = _wg_write_conf(text)
    except OSError as e:
        return _hl_done({"success": False, "verified": False, "output": f"Write failed: {e}"})
    out.append("Takes effect from the next tunnel stop; no restart needed.")
    return _hl_done({"success": True, "verified": True, "output": "\n".join(out)})

def action_health_restart_tunnel() -> dict:
    err = _require_root()
    if err:
        return err
    if _half_mode() == "testing":
        return {"success": False, "verified": False,
                "output": "Refused: a half-tunnel test is running (it runs wg0 from a copy). Use Undo now first."}
    if not os.path.exists(WG0_CONF_PATH):
        return {"success": False, "verified": False, "output": "No wg0.conf."}
    gate: list[str] = []
    if not _wg_dns_gate(gate):
        return _hl_done({"success": False, "verified": False, "output": "\n".join(gate)})
    cur = _hl_read_conf() or ""
    if _wg_apply_endpoint_pin(cur)[1] or _wg_legacy_fix(cur)[1]:
        try:
            gate += _wg_write_conf(cur)
        except OSError as e:
            return _hl_done({"success": False, "verified": False, "output": "\n".join(gate + [f"Write failed: {e}"])})
    unit = "wg-quick@wg0" if _wg_quick_template_available() else "44net-tunnel.service"
    t0 = int(time.time())
    r = _run_argv(["systemctl", "restart", unit], timeout=_WG_START_WAIT)
    lines = gate + ([r["output"]] if r["output"] else [])
    if not r["success"]:
        lines += _wg_start_report(unit, t0)
        return _hl_done({"success": False, "verified": False, "output": "\n".join(lines)})
    hs = _half_wait_handshake()
    lines.append("ok    tunnel restarted" + ("; handshake with the 44Net server" if hs else "; no handshake yet, check again in a minute"))
    return _hl_done({"success": True, "verified": hs, "output": "\n".join(lines)})

def build_tunnel_health(force: bool = False) -> dict:
    items = _ov_endpoint_findings_cached(force) + _ov_health_findings(force=force)
    return {"items": items, "conf_exists": os.path.exists(WG0_CONF_PATH),
            "testing": "half" if _half_mode() == "testing" else ("fullx" if _fx_mode() == "testing" else ""),
            "root": os.geteuid() == 0, "checked_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S")}

def _route_tunnel_health(query: dict) -> tuple[int, str, bytes]:
    force = (query.get("force") or [""])[0] == "1"
    return 200, "application/json", json.dumps(build_tunnel_health(force)).encode("utf-8")

def _self_check_worst_level(findings: list[dict]) -> str:
    order = {"danger": 3, "warn": 2, "info": 1, "ok": 0}
    if not findings:
        return "ok"
    return max(findings, key=lambda f: order.get(f["level"], 0))["level"]

