def _run_argv(argv: list[str], timeout: int = 20) -> dict:
    log(f"RUN: {' '.join(argv)}")
    try:
        r = subprocess.run(argv, capture_output=True, text=True, timeout=_fw_timeout(argv, timeout))
        ok = r.returncode == 0
        out = (r.stdout or "") + (r.stderr or "")
        log(f"{'OK' if ok else 'FAIL'} (exit {r.returncode}): {' '.join(argv)}")
        return {"success": ok, "returncode": r.returncode, "output": out.strip()}
    except FileNotFoundError:
        log(f"FAIL (not found): {' '.join(argv)}")
        return {"success": False, "returncode": None, "output": f"{argv[0]}: command not found"}
    except subprocess.TimeoutExpired:
        log(f"FAIL (timeout): {' '.join(argv)}")
        return {"success": False, "returncode": None, "output": "command timed out"}

def _require_root() -> dict | None:
    if os.geteuid() != 0:
        return {"success": False, "returncode": None,
                "output": "This action requires root. Run 44helper via its systemd service (installed with --install)."}
    return None

_APT_MUTATING_RE = re.compile(
    r"\b(?:apt|apt-get|aptitude)\b(?!-cache)[^;&|\n]*?\b(?:install|reinstall|upgrade|full-upgrade|"
    r"dist-upgrade|remove|purge|autoremove|autopurge)\b(?!-)"
    r"|\bdpkg\b[^;&|\n]*?(?:--configure|--install|--remove|--purge|--unpack|\s-[iPr]\b)")
_DPKG_PROGRESS_RE = re.compile(r"^\(Reading database \.\.\.\s*(?:\d+%)?\s*$")

_BUILD_CMD_RE = re.compile(r"(?:^|[\s;&|(])(?:make|cmake|ninja|meson)(?:\s|$)|\./configure(?:\s|$)")

def _is_build_cmd(cmd: str) -> bool:
    return bool(_BUILD_CMD_RE.search(cmd or ""))

def _is_apt_mutating(cmd: str) -> bool:
    return bool(_APT_MUTATING_RE.search(cmd or ""))

_SCRIPT_INSTALL_RE = re.compile(
    r"\|\s*(?:sudo\s+(?:-\S+\s+)*)?(?:ba)?sh\b"
    r"|(?:\./|\b(?:ba)?sh\s+)[\w./-]*install[\w.-]*\.sh\b"
    r"|\b(?:ba)?sh\s+\.?/\S+")

def _is_script_install(cmd: str) -> bool:
    return bool(_SCRIPT_INSTALL_RE.search(cmd or ""))

def _effective_timeout(cmd: str, timeout):
    return None if (_is_apt_mutating(cmd) or _is_build_cmd(cmd) or _is_script_install(cmd)) else timeout

def _strip_progress_noise(text: str) -> str:
    return "".join(l for l in (text or "").splitlines(keepends=True)
                   if not _DPKG_PROGRESS_RE.match(l.rstrip("\r\n")))

def _stop_process_tree(proc: "subprocess.Popen", grace: float = 10.0) -> None:
    for sig, wait in ((signal.SIGTERM, grace), (signal.SIGKILL, 5.0)):
        try:
            os.killpg(proc.pid, sig)
        except (ProcessLookupError, PermissionError, OSError):
            return
        try:
            proc.wait(timeout=wait)
            return
        except subprocess.TimeoutExpired:
            continue

def _run_shell_line(cmd: str, timeout: int = 900) -> dict:
    log(f"RUN(shell): {cmd}")
    timeout = _effective_timeout(cmd, timeout)
    try:
        proc = subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                text=True, start_new_session=True)
        try:
            so, se = proc.communicate(timeout=timeout)
        except subprocess.TimeoutExpired:
            _stop_process_tree(proc)
            proc.communicate()
            raise
        r = subprocess.CompletedProcess(cmd, proc.returncode, so, se)
        ok = r.returncode == 0
        out = _strip_progress_noise((r.stdout or "") + (r.stderr or ""))
        log(f"{'OK' if ok else 'FAIL'} (exit {r.returncode}): {cmd}")
        return {"success": ok, "returncode": r.returncode, "output": out.strip()}
    except subprocess.TimeoutExpired:
        log(f"FAIL (timeout): {cmd}")
        return {"success": False, "returncode": None, "output": _timeout_message(cmd, timeout).lstrip("\n")}
    except Exception as exc:
        log(f"FAIL (exception): {cmd} :: {exc}")
        return {"success": False, "returncode": None, "output": f"error running command: {exc}"}

_JOBS: dict[str, dict] = {}
_JOBS_LOCK = threading.Lock()
_JOB_OUTPUT_CAP = 64 * 1024
_JOB_IDLE_TTL = 600

def _job_append_output(job_key: str, text: str) -> None:
    if not text:
        return
    with _JOBS_LOCK:
        job = _JOBS.get(job_key)
        if job is None:
            return
        job["output"] += text
        job["out_seq"] = job.get("out_seq", 0) + len(text)
        if len(job["output"]) > _JOB_OUTPUT_CAP:
            overflow = len(job["output"]) - _JOB_OUTPUT_CAP
            job["output"] = "(...output truncated...)\n" + job["output"][overflow:]
    _ev_notify()

def _prune_stale_jobs() -> None:
    cutoff = time.time() - _JOB_IDLE_TTL
    with _JOBS_LOCK:
        stale = [k for k, v in _JOBS.items()
                 if v["status"] == "done" and v.get("finished_at", v["started_at"]) < cutoff]
        for k in stale:
            del _JOBS[k]

def _timeout_message(cmd: str, timeout: int) -> str:
    if _is_apt_mutating(cmd):
        return (f"\ncommand was STOPPED after {timeout}s while changing packages. The system may be "
                f"half-updated. Do NOT reboot yet. On the Update tab: 1) run 'Is apt still running?' and "
                f"wait until it reports nothing running, 2) run step 2's 'Reconfigure half-installed "
                f"packages' (sudo dpkg --force-confdef --force-confold --configure -a), 3) run step 2 itself, 4) re-run the step that "
                f"was stopped. Reboot only after all of that succeeds.")
    if "apt" in cmd:
        return (f"\ncommand timed out after {timeout}s and was stopped. It only reads package "
                f"information (changes nothing), so it is safe to run again -- a slow mirror is the "
                f"usual cause.")
    return (f"\ncommand timed out after {timeout}s and was stopped, including anything it started. "
            f"If this command normally expects interactive input, note this engine has no stdin "
            f"channel to supply it.")

def _job_worker(job_key: str, cmd: str, timeout: int) -> None:
    log(f"RUN(shell,async): {cmd}")
    start = time.time()
    try:
        proc = subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE,
                                 stderr=subprocess.STDOUT, text=True, bufsize=1,
                                 start_new_session=True)
    except Exception as exc:
        with _JOBS_LOCK:
            job = _JOBS.get(job_key)
            if job is not None:
                job.update(status="done", success=False, returncode=None,
                           output=f"error starting command: {exc}", finished_at=time.time())
        log(f"FAIL (exception starting): {cmd} :: {exc}")
        return

    timed_out = False
    while True:
        ready, _, _ = select.select([proc.stdout], [], [], 1.0)
        if ready:
            line = proc.stdout.readline()
            if line:
                if not _DPKG_PROGRESS_RE.match(line.rstrip("\r\n")):
                    _job_append_output(job_key, line)
            elif proc.poll() is not None:
                break
        elif proc.poll() is not None:
            break
        if timeout is not None and time.time() - start > timeout:
            timed_out = True
            _stop_process_tree(proc)
            break
    proc.wait()
    try:
        proc.stdout.close()
    except Exception:
        pass
    rc = proc.returncode

    with _JOBS_LOCK:
        job = _JOBS.get(job_key)
        if job is None:
            return
        if timed_out:
            job["output"] = job["output"] + _timeout_message(cmd, timeout)
            job["success"] = False
            job["returncode"] = None
        else:
            job["success"] = (rc == 0)
            job["returncode"] = rc
        job["status"] = "done"
        job["finished_at"] = time.time()
    _ev_notify()
    log(f"{'OK' if (not timed_out and rc == 0) else 'FAIL'} (exit {rc}): {cmd}")

def _start_shell_job(job_key: str, cmd: str, timeout: int = 900) -> dict:
    with _JOBS_LOCK:
        existing = _JOBS.get(job_key)
        if existing is not None and existing["status"] == "running":
            return {"job_key": job_key, "status": "running"}
        _JOBS[job_key] = {"status": "running", "output": "", "success": None,
                           "returncode": None, "started_at": time.time(), "cmd": cmd}
    timeout = _effective_timeout(cmd, timeout)
    threading.Thread(target=_job_worker, args=(job_key, cmd, timeout), daemon=True).start()
    return {"job_key": job_key, "status": "running"}

def _job_python_worker(job_key: str, fn: Callable[[], dict]) -> None:
    log(f"RUN(python-job): {job_key}")
    try:
        result = fn()
    except Exception as exc:
        with _JOBS_LOCK:
            job = _JOBS.get(job_key)
            if job is not None:
                job.update(status="done", success=False, verified=False,
                           output=f"error: {exc}", finished_at=time.time())
        log(f"FAIL (exception): {job_key} :: {exc}")
        return
    with _JOBS_LOCK:
        job = _JOBS.get(job_key)
        if job is not None:
            job.update(status="done", success=bool(result.get("success")),
                       verified=result.get("verified"),
                       output=str(result.get("output", "")), finished_at=time.time())
    log(f"{'OK' if result.get('success') else 'FAIL'} (python-job): {job_key}")

def _start_python_job(job_key: str, fn: Callable[[], dict]) -> dict:
    with _JOBS_LOCK:
        existing = _JOBS.get(job_key)
        if existing is not None and existing["status"] == "running":
            return {"job_key": job_key, "status": "running"}
        _JOBS[job_key] = {"status": "running", "output": "", "success": None,
                           "verified": None, "returncode": None, "started_at": time.time()}
    threading.Thread(target=_job_python_worker, args=(job_key, fn), daemon=True).start()
    return {"job_key": job_key, "status": "running"}

def _job_status(job_key: str) -> dict:
    _prune_stale_jobs()
    with _JOBS_LOCK:
        job = _JOBS.get(job_key)
    if job is None:
        unit = _job_unit_name(job_key)
        if unit in _unit_jobs_present():
            _adopt_unit_job(job_key, unit)
    with _JOBS_LOCK:
        job = _JOBS.get(job_key)
        if job is None:
            return {"job_key": job_key, "status": "unknown", "output": "", "success": None,
                     "returncode": None, "verified": None}
        end = time.time() if job["status"] == "running" else job.get("finished_at", time.time())
        return {"job_key": job_key, "status": job["status"], "output": job["output"],
                "success": job.get("success"), "returncode": job.get("returncode"),
                "verified": job.get("verified"),
                "elapsed_sec": int(max(0, end - job.get("started_at", end)))}

_EV_COND = threading.Condition()
_EV_STREAMS = 0
_EV_MAX_STREAMS = 4
_EV_KEEPALIVE = 15.0
_EV_TICK = 1.0
_EV_COALESCE = 0.15

def _ev_notify() -> None:
    with _EV_COND:
        _EV_COND.notify_all()

def _ev_write(wfile, event: str, data) -> None:
    payload = json.dumps(data, separators=(",", ":"))
    wfile.write(f"event: {event}\ndata: {payload}\n\n".encode("utf-8"))
    wfile.flush()

def _ev_job_diffs(sent: dict) -> list[dict]:
    with _JOBS_LOCK:
        snap = {k: (v.get("started_at"), v.get("out_seq", 0), v.get("output", ""), v.get("status"),
                    v.get("success"), v.get("returncode"), v.get("verified"), v.get("finished_at"))
                for k, v in _JOBS.items()}
    out: list[dict] = []
    for k, (st, seq, output, status, succ, rc, ver, fin) in snap.items():
        meta = (status, succ, rc, ver, fin)
        prev = sent.get(k)
        ent = {"key": k, "status": status, "success": succ, "returncode": rc, "verified": ver,
               "started_at": st, "finished_at": fin}
        if prev is None or prev[0] != st or (status == "done" and prev[2][0] != "done"):
            ent["output"] = output
            ent["reset"] = True
        else:
            d = seq - prev[1]
            if d <= 0:
                if meta == prev[2]:
                    continue
            elif d <= len(output):
                ent["append"] = output[-d:]
            else:
                ent["output"] = output
                ent["reset"] = True
        sent[k] = (st, seq, meta)
        out.append(ent)
    for k in list(sent):
        if k not in snap:
            out.append({"key": k, "gone": True})
            del sent[k]
    return out

_EV_WATCH: dict = {"overview": None, "ov_fp": None, "ov_rev": 0, "ov_at": 0.0,
                   "quiet": None, "qm_fp": None, "qm_rev": 0, "qm_at": 0.0, "running": False}
_EV_WATCH_LOCK = threading.Lock()
_EV_OV_EVERY = 5.0
_EV_QM_EVERY = 10.0

def _ev_watcher_ensure() -> None:
    with _EV_WATCH_LOCK:
        if _EV_WATCH["running"]:
            return
        _EV_WATCH["running"] = True
    threading.Thread(target=_ev_watcher_loop, daemon=True).start()

def _ev_watch_step(now: float) -> bool:
    changed = False
    if now - _EV_WATCH["ov_at"] >= _EV_OV_EVERY:
        _EV_WATCH["ov_at"] = now
        try:
            data = build_overview_data(_cfg)
            fp = json.dumps({k: v for k, v in data.items() if k != "checked_at"}, sort_keys=True, default=str)
            if fp != _EV_WATCH["ov_fp"]:
                with _EV_WATCH_LOCK:
                    _EV_WATCH.update(overview=data, ov_fp=fp, ov_rev=_EV_WATCH["ov_rev"] + 1)
                changed = True
        except Exception as exc:
            log(f"live-update watcher: overview check failed: {exc}")
    if now - _EV_WATCH["qm_at"] >= _EV_QM_EVERY:
        _EV_WATCH["qm_at"] = now
        try:
            data = _qm_status()
            fp = json.dumps(data, sort_keys=True, default=str)
            if fp != _EV_WATCH["qm_fp"]:
                with _EV_WATCH_LOCK:
                    _EV_WATCH.update(quiet=data, qm_fp=fp, qm_rev=_EV_WATCH["qm_rev"] + 1)
                changed = True
        except Exception as exc:
            log(f"live-update watcher: quiet-mode check failed: {exc}")
    return changed

def _ev_watcher_loop() -> None:
    while True:
        with _EV_WATCH_LOCK:
            with _EV_COND:
                n = _EV_STREAMS
            if n <= 0:
                _EV_WATCH["running"] = False
                _EV_WATCH["ov_at"] = _EV_WATCH["qm_at"] = 0.0
                return
        if _ev_watch_step(time.monotonic()):
            _ev_notify()
        time.sleep(1.0)

def _ev_watch_diffs(seen: dict) -> list[tuple[str, dict]]:
    out = []
    with _EV_WATCH_LOCK:
        for name, rev_key in (("overview", "ov_rev"), ("quiet", "qm_rev")):
            if _EV_WATCH[name] is not None and seen.get(name) != _EV_WATCH[rev_key]:
                seen[name] = _EV_WATCH[rev_key]
                out.append((name, _EV_WATCH[name]))
    return out

def _ev_serve(wfile, alive: Callable[[], bool], max_seconds: float | None = None) -> None:
    sent: dict = {}
    seen: dict = {}
    t0 = last_write = time.monotonic()
    wfile.write(b"retry: 5000\n\n")
    wfile.flush()
    first = True
    while True:
        if not alive():
            _ev_write(wfile, "bye", {"reason": "logged_out"})
            return
        _prune_stale_jobs()
        batch = _ev_job_diffs(sent)
        if batch or first:
            _ev_write(wfile, "jobs", {"now": time.time(), "full": first, "jobs": batch})
            last_write = time.monotonic()
            first = False
        for name, data in _ev_watch_diffs(seen):
            _ev_write(wfile, name, data)
            last_write = time.monotonic()
        if time.monotonic() - last_write >= _EV_KEEPALIVE:
            wfile.write(b": ka\n\n")
            wfile.flush()
            last_write = time.monotonic()
        if max_seconds is not None and time.monotonic() - t0 >= max_seconds:
            return
        with _EV_COND:
            _EV_COND.wait(timeout=_EV_TICK)
        time.sleep(_EV_COALESCE)

def _cockpit_install_step(num: int) -> dict:
    return {
        "id": "install_cockpit", "num": num, "title": "Install Cockpit (web admin UI)",
        "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt install -y "
               "-o Dpkg::Options::=\"--force-confdef\" -o Dpkg::Options::=\"--force-confold\" "
               "cockpit cockpit-networkmanager cockpit-packagekit cockpit-storaged cockpit-system cockpit-ws",
        "timeout": 900,
        "note": "Cockpit is a browser-based admin console (port 9090) — not specific to this tab's software "
                "stack, so this same step appears on ASL3/DVSwitch/SVXLink/M17 alike. Installing it more "
                "than once across tabs is a harmless no-op (apt skips packages already installed) — run it "
                "once from whichever tab you set up first, skip it on the others.",
    }

def _cockpit_enable_step(num: int) -> dict:
    return {
        "id": "enable_cockpit", "num": num, "title": "Enable Cockpit socket",
        "cmd": "sudo systemctl enable --now cockpit.socket",
        "note": "Idempotent — safe to run again from another tab if Cockpit was already installed/enabled "
                "from there.",
    }

def _cockpit_purge_step(num: int) -> dict:
    return {
        "id": "purge_cockpit", "num": num, "title": "(Optional) Stop & purge Cockpit",
        "cmd": "sudo systemctl disable --now cockpit.socket 2>&1; "
               "sudo DEBIAN_FRONTEND=noninteractive apt purge -y cockpit cockpit-networkmanager "
               "cockpit-packagekit cockpit-storaged cockpit-system cockpit-ws",
        "auto": False,
        "confirm_text": ("Remove Cockpit completely?\n\n"
                         "This uninstalls Cockpit, the web admin panel and its web terminal, for the WHOLE "
                         "node -- not just this tab. Anything else on this node that uses Cockpit loses it "
                         "too.\n\nIf you are using Cockpit's web terminal right now, that session will "
                         "cut off partway through.\n\nPress OK only if this is really what you want."),
        "note": "NOT run automatically as part of a normal purge pass — since v0.0.44 any of the four "
                "install tabs can install Cockpit independently, purging it here would also take it away "
                "from whichever other tab's stack is relying on it. Only run this if you're sure nothing "
                "else on this node still wants Cockpit.",
    }

def _config_save_step(step_id: str, num: int) -> dict:
    return {"id": step_id, "num": num, "title": "Save original configs as Restore point",
            "config_save": True,
            "note": "Do not run this until ASL3, DVSwitch and USRP2M17 (whichever of them you will use) are all "
                    "installed and set up. It saves the config files of every installed system to the library as "
                    "the Restore point, once. Running it again only adds systems installed since; saved files are "
                    "never overwritten. The Restore point, save points and presets are on the Config tab."}

def _asl3_install_steps(distro_deb_suffix: str) -> list[dict]:
    return [
        {"id": "prereqs", "num": 1, "title": "Install prerequisites",
         "cmd": "sudo apt update && sudo DEBIAN_FRONTEND=noninteractive apt install -y "
                "-o Dpkg::Options::=\"--force-confdef\" -o Dpkg::Options::=\"--force-confold\" "
                "wget curl git dpkg sudo "
                "firewalld alsa-utils python3-serial"},
        {"id": "fetch_repo", "num": 2, "title": "Download ASL3 repo package",
         "cmd": f"cd /tmp && sudo wget https://repo.allstarlink.org/public/asl-apt-repos.{distro_deb_suffix}_all.deb",
         "note": "Adapted from the source doc's separate `cd /tmp` line — each step here runs in its own "
                 "subprocess, so cd alone would not carry over to the next step."},
        {"id": "install_repo", "num": 3, "title": "Install ASL3 repo package",
         "cmd": f"sudo dpkg -i /tmp/asl-apt-repos.{distro_deb_suffix}_all.deb",
         "note": "Uses the absolute /tmp path rather than a bare filename, since working directory does not "
                 "persist between steps in this engine."},
        {"id": "apt_update", "num": 4, "title": "Refresh package index",
         "cmd": "sudo apt update"},
        {"id": "install_asl3_core", "num": 5, "title": "Install ASL3 core",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt install -y "
                "-o Dpkg::Options::=\"--force-confdef\" -o Dpkg::Options::=\"--force-confold\" asl3",
         "timeout": 900},
        {"id": "install_allmon3", "num": 6, "title": "Install Allmon3",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt install -y "
                "-o Dpkg::Options::=\"--force-confdef\" -o Dpkg::Options::=\"--force-confold\" allmon3"},
        _cockpit_install_step(7),
        _cockpit_enable_step(8),
        {"id": "install_node_utils", "num": 9, "title": "Install node database / TTS utilities",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt install -y "
                "-o Dpkg::Options::=\"--force-confdef\" -o Dpkg::Options::=\"--force-confold\" "
                "asl3-update-nodelist asl3-tts"},
        {"id": "install_appliance", "num": 10, "title": "(Optional) Full ASL3 Appliance branding/firewall defaults",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt install -y "
                "-o Dpkg::Options::=\"--force-confdef\" -o Dpkg::Options::=\"--force-confold\" "
                "asl3-appliance asl3-appliance-pi",
         "timeout": 900,
         "note": "Optional per source doc — applies appliance branding, web rules, and pre-configured "
                 "firewall defaults. asl3-appliance-pi is the Raspberry Pi-specific companion package (all "
                 "652701/652702/652703 nodes are Pi-based) — it pulls in apache2 for its fallback-AP "
                 "WiFi-setup feature, confirmed expected on a live test. Current AllStarLink docs describe "
                 "the manual add-appliance-to-an-existing-install path as Debian 13 (Trixie) only, though a "
                 "live hardware test on this node's own Bookworm install had this package install and work "
                 "fine — so treat that doc wording with a grain of salt rather than as a hard Bookworm "
                 "blocker, but keep an eye out if a fresh Bookworm install ever fails here. Skip entirely if "
                 "you don't want appliance branding. Kept as one step (not split further) since both "
                 "packages are a matched pair for this fleet's Pi-based nodes, unlike the asl3/allmon3/"
                 "cockpit/node-utils grouping this version split apart — those were three unrelated software "
                 "components bundled into one apt line, not a matched pair."},
        {"id": "allmon3_delete_default", "num": 11, "title": "Remove default Allmon3 account",
         "cmd": "sudo allmon3-passwd --delete allmon3"},
        {"id": "allmon3_set_admin", "num": 12, "title": "Set Allmon3 admin password",
         "fields": [
             {"id": "username", "label": "Username", "type": "text", "default": "admin"},
             {"id": "password", "label": "Password", "type": "password", "default": ""},
         ],
         "cmd_template": "sudo allmon3-passwd --password {{password}} {{username}} && sleep 2 && "
                          "sudo systemctl restart allmon3",
         "cmd": "sudo allmon3-passwd --password CHANGE_ME admin && sleep 2 && sudo systemctl restart allmon3",
         "note": "Fill in Username/Password above instead of editing a command line. allmon3-passwd's "
                 "--password PASSWORD flag makes this non-interactive (no stdin channel needed), then a "
                 "2-second pause and systemctl restart allmon3 apply the change. Heads up: the password "
                 "will briefly appear in the shell's process list (ps) and, depending on shell config, in "
                 "command history — acceptable for a one-time node setup step, but don't reuse a sensitive "
                 "password here."},
        {"id": "enable_allmon3", "num": 13, "title": "Enable Allmon3 service",
         "cmd": "sudo systemctl enable --now allmon3"},
        {"id": "enable_astdb_timer", "num": 14, "title": "Enable node database updater timer",
         "cmd": "sudo systemctl enable --now asl3-update-astdb.timer"},
        {"id": "run_asl_menu", "num": 15, "title": "Configure node settings (asl-menu)",
         "cmd": "sudo asl-menu",
         "manual": True,
         "note": "INTERACTIVE — full-screen console menu, not a one-shot command. This engine has no stdin "
                 "channel to drive it, so it is not run via the Run button here. SSH into the node (or use "
                 "the Cockpit terminal at the address shown for the Cockpit-socket step above) and run "
                 "`sudo asl-menu` there to complete Node Settings / radio interface configuration."},
        _config_save_step("asl3_save_restore", 16),
    ]

_ASL3_INSTALL_BOOKWORM: list[dict] = _asl3_install_steps("deb12")
_ASL3_INSTALL_TRIXIE: list[dict] = _asl3_install_steps("deb13")

def _asl3_purge_steps() -> list[dict]:
    return [
        {"id": "purge_stop_services", "num": 1, "title": "Stop & disable ASL3-related services",
         "cmd": "sudo systemctl disable --now asl3-update-astdb.timer allmon3 2>&1; true",
         "note": "Reverses install steps' enable_allmon3/enable_astdb_timer. Trailing `; true` so this step "
                 "doesn't report failure if a unit was never installed. Cockpit is NOT stopped here since "
                 "v0.0.44 — see purge_cockpit below, the optional step that replaces it."},
        {"id": "purge_packages", "num": 2, "title": "Purge ASL3 and Allmon3 packages",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt purge -y asl3 asl3-appliance asl3-appliance-pi "
                "asl3-update-nodelist asl3-tts allmon3",
         "note": "Reverses install_asl3_core/install_allmon3/install_node_utils and the optional "
                 "install_appliance step. `purge` (not `remove`) also drops each package's own config "
                 "files. apt skips any package name here that isn't currently installed rather than failing "
                 "the whole command. Cockpit packages moved out of this list in v0.0.44 (now a shared "
                 "cross-tab step) — see purge_cockpit below."},
        {"id": "purge_autoremove", "num": 3, "title": "Remove now-unused dependencies",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt autoremove -y --purge"},
        {"id": "purge_repo", "num": 4, "title": "Remove the ASL3 apt repository package",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt purge -y asl-apt-repos && sudo apt update",
         "note": "Reverses install_repo — drops the repo.allstarlink.org apt source, then refreshes the index "
                 "so apt stops treating those packages as available from a repo that's no longer configured."},
        {"id": "purge_cleanup_tmp", "num": 5, "title": "Clean up downloaded repo package file",
         "cmd": "sudo rm -f /tmp/asl-apt-repos.*.deb",
         "note": "Removes the leftover .deb fetched in install step 2 (fetch_repo)."},
        {"id": "purge_config", "num": 6, "title": "(Optional) Remove leftover node config",
         "cmd": "sudo rm -rf /etc/asterisk",
         "auto": False,
         "note": "NOT run automatically as part of a normal purge pass — this deletes rpt.conf and any other "
                 "Asterisk/ASL3 config, including node number, callsign, and radio-interface settings entered "
                 "through asl-menu (install step 12), which `apt purge` does not always remove on its own. Only "
                 "run this if you actually want a completely clean slate for a fresh install; skip it if you "
                 "plan to reinstall onto the same node identity."},
        _cockpit_purge_step(7),
    ]

