def _dv_web_clash_steps(first_num: int) -> list[dict]:
    return [
        {"id": "web_clash_disable_lighttpd", "num": first_num,
         "title": "(Optional) Web-server clash: turn off the DVSwitch web dashboard",
         "cmd": _DV_NO_CLASH_GUARD + "sudo systemctl disable --now lighttpd && echo 'lighttpd stopped and "
                "disabled -- apache2 (ASL3 / Allmon3) keeps port 80.'",
         "confirm_text": ("Turn off lighttpd?\n\nThis stops the DVSwitch web dashboard so apache2 (ASL3 / "
                          "Allmon3) can keep port 80. DVSwitch itself keeps working; only its web page goes "
                          "away. You can turn it back on later with: sudo systemctl enable --now lighttpd"),
         "note": "Only needed when step 1 (or this step) reports a CLASH. Does nothing if there is no clash."},
        {"id": "web_clash_move_lighttpd", "num": first_num + 1,
         "title": "(Optional) Web-server clash: move the DVSwitch web dashboard to another port",
         "fields": [{"id": "port", "label": "New port for the DVSwitch dashboard", "type": "text",
                     "default": "8081"}],
         "cmd_template": ("case '{{port}}' in ''|*[!0-9]*) echo 'Port must be a number'; exit 1;; esac; "
                          "if [ '{{port}}' -lt 1 ] || [ '{{port}}' -gt 65535 ]; then "
                          "echo 'Port must be between 1 and 65535.'; exit 1; fi; "
                          "case '{{port}}' in " + "|".join(p for p, _ in _DV_RESERVED_PORTS) + ") "
                          "echo 'Port {{port}} belongs to another tool on this node -- pick another (8081 is the default).'; "
                          "exit 1;; esac; "
                          "if ss -ltnH 'sport = :{{port}}' 2>/dev/null | grep -q .; then "
                          "echo 'Something is already listening on port {{port}} -- pick another.'; exit 1; fi; "
                          + _DV_NO_CLASH_GUARD +
                          "sudo cp -n /etc/lighttpd/lighttpd.conf /etc/lighttpd/lighttpd.conf.44helper-bak && "
                          "if grep -qE '^[[:space:]]*server\\.port' /etc/lighttpd/lighttpd.conf; then "
                          "sudo sed -i -E 's/^[[:space:]]*server\\.port[[:space:]]*=.*/server.port = {{port}}/' "
                          "/etc/lighttpd/lighttpd.conf; "
                          "else echo 'server.port = {{port}}' | sudo tee -a /etc/lighttpd/lighttpd.conf >/dev/null; fi && "
                          "sudo lighttpd -tt -f /etc/lighttpd/lighttpd.conf && sudo systemctl restart lighttpd && "
                          "systemctl is-active lighttpd && "
                          "echo 'DVSwitch dashboard now on port {{port}} -- open http://<this node>:{{port}}/'"),
         "confirm_text": ("Move the DVSwitch web dashboard off port 80?\n\nThis edits /etc/lighttpd/lighttpd.conf "
                          "(a backup is kept as lighttpd.conf.44helper-bak), checks the new config, and restarts "
                          "lighttpd. apache2 (ASL3 / Allmon3) keeps port 80."),
         "note": "Only needed when step 1 (or this step) reports a CLASH. Keeps both web pages: Allmon3 on port "
                 "80, the DVSwitch dashboard on the port you choose (LAN only -- don't open it to the tunnel "
                 "zone; check the Ports tab afterwards). Does nothing if there is no clash."},
    ]

_DV_PREFLIGHT_CMD = (
    "echo '--- processor type:'; dpkg --print-architecture; "
    "echo '--- DVSwitch package source:'; "
    f"if {_DV_SRC_TEST}; then echo 'present -- steps 2 and 3 will skip themselves'; "
    "else echo 'NOT found -- steps 2 and 3 will add it'; fi; "
    "echo '--- components (package / program files):'; "
    "for pair in analog-bridge:Analog_Bridge mmdvm-bridge:MMDVM_Bridge md380-emu:md380-emu; do "
    "p=${pair%%:*}; d=${pair#*:}; "
    "s=$(dpkg-query -W -f='${Status}' $p 2>/dev/null); "
    "case \"$s\" in *' installed') ps='installed';; ''|*not-installed) ps='NOT installed';; "
    "*unpacked|*half-configured|*half-installed|*triggers-awaited|*triggers-pending) "
    "ps='HALF-INSTALLED -- run Package recovery 2 on the Update tab';; "
    "*config-files) ps='removed, settings left behind -- the purge cleans this up';; *) ps=\"$s\";; esac; "
    "if [ -n \"$(ls -A /opt/$d 2>/dev/null)\" ]; then fs='files present'; else fs='files MISSING'; fi; "
    "echo \"$p: $ps / $fs\"; done; "
    "echo '--- services:'; "
    f"for u in {_DV_UNITS}; do "
    "if systemctl cat $u.service >/dev/null 2>&1; then echo \"$u: found\"; else echo \"$u: NOT found\"; fi; done; "
    + _DV_WEB_CHECK +
    "true"
)

_DV_INSTALL_CMD = (
    f"sudo DEBIAN_FRONTEND=noninteractive apt install -y {_DV_APT_OPTS} {_DV_COMPONENTS} && "
    "for pair in analog-bridge:Analog_Bridge mmdvm-bridge:MMDVM_Bridge md380-emu:md380-emu; do "
    "p=${pair%%:*}; d=${pair#*:}; "
    "if [ -z \"$(ls -A /opt/$d 2>/dev/null)\" ]; then "
    "echo \"/opt/$d is empty -- re-installing $p to restore its files and config\"; "
    f"sudo DEBIAN_FRONTEND=noninteractive apt install -y --reinstall {_DV_APT_OPTS} "
    "-o Dpkg::Options::=\"--force-confmiss\" $p || exit 1; fi; done"
)

_DV_ENABLE_CMD = (
    "found=''; missing=''; "
    f"for u in {_DV_UNITS}; do "
    "if systemctl cat $u.service >/dev/null 2>&1; then found=\"$found $u\"; else missing=\"$missing $u\"; fi; done; "
    "if [ -n \"$found\" ]; then sudo systemctl enable --now $found || exit 1; echo \"enabled:$found\"; fi; "
    "if [ -n \"$missing\" ]; then echo \"NOT installed as services:$missing -- re-run the install step\"; exit 1; fi"
)

_DV_GATEWAYS_ENABLE_CMD = (
    "found=''; missing=''; "
    "for u in ircddbgatewayd ysfgateway p25gateway nxdngateway; do "
    "if systemctl cat $u.service >/dev/null 2>&1; then found=\"$found $u\"; else missing=\"$missing $u\"; fi; done; "
    "if systemctl cat stfu.service >/dev/null 2>&1; then found=\"$found stfu\"; fi; "
    "if [ -n \"$found\" ]; then sudo systemctl enable --now $found || exit 1; echo \"enabled:$found\"; fi; "
    "if [ -n \"$missing\" ]; then echo \"NOT installed as services:$missing -- re-run the DVSwitch install step\"; exit 1; fi"
)
_DV_GATEWAYS_NOTE = ("Enables and starts the digital-mode gateways: ircddbgatewayd (D-Star and XLX), ysfgateway (YSF and "
                     "FCS), p25gateway, nxdngateway, and stfu when it exists. p25gateway and nxdngateway are installed "
                     "but disabled, so without this step P25 and NXDN do not work until their dashboard page is "
                     "opened. FAILS naming any of the four that are not installed as services. The dashboard still "
                     "starts and restarts a gateway when you open and leave its page.")

_DV_DISABLE_CMD = (
    f"for u in {_DV_UNITS}; do "
    "if systemctl cat $u.service >/dev/null 2>&1; then sudo systemctl disable --now $u 2>&1; "
    "else echo \"$u: not installed, skipping\"; fi; done; true"
)

def _dv_fetch_repo_cmd(flag: str = "") -> str:
    return (f"if {_DV_SRC_TEST}; then echo 'DVSwitch source already set up -- skipping'; "
            f"else cd /tmp && sudo wget {flag}http://dvswitch.org/bookworm; fi")

def _dv_run_repo_cmd() -> str:
    return (f"if {_DV_SRC_TEST}; then echo 'DVSwitch source already set up -- skipping'; "
            "else cd /tmp && sudo bash ./bookworm; fi")

_DV_REPO_NOTE = ("Official dvswitch.org script, written for Debian 12 — adds the DVSwitch apt source and signing "
                 "key. Fetched over plain HTTP (no TLS); review it if you want to confirm before trusting it on a "
                 "node. Run with `sudo bash` rather than executed directly, because some images mount /tmp so "
                 "programs cannot run from it. Skips itself if the source is already set up.")
_DV_INSTALL_NOTE = ("Installs the dvswitch-server bundle AND its working parts by name (analog-bridge, mmdvm-bridge, "
                    "md380-emu) — the bundle alone has been seen installed with the parts missing. Any part whose "
                    "/opt folder is empty is then re-installed with --force-confmiss so deleted files and .ini "
                    "config come back. The bridge units depend on netcheck.service; if the bridges won't start "
                    "with the tunnel up, see the netcheck troubleshooting card on the tunnel tabs.")
_DV_ENABLE_NOTE = ("Enables and starts whichever of analog_bridge / mmdvm_bridge / md380-emu exist, and FAILS naming "
                   "any that are missing (a plain `systemctl enable a b c` aborts on the first missing one and "
                   "enables nothing).")

def _dv_netcheck_step(step_id: str, num: int) -> dict:
    return {"id": step_id, "num": num, "title": "Start DVSwitch after the network is ready",
            "pi_action": "dv_boot_ready", "button": "Set the boot order",
            "note": "At boot the DVSwitch services can start before the network, the 44Net tunnel or DNS are up; "
                    "netcheck then fails and the gateways can't reach their servers. This applies the netcheck "
                    "fixes, and makes netcheck, the bridges and the gateways wait (up to 3 minutes) for the "
                    "network, the tunnel handshake and DNS, with a retry if one still fails. Safe to run again; "
                    "step 6 of either tunnel tab also does it. Remove is on the boot-order card under tunnel step 6."}

def _dvswitch_install_steps_bookworm() -> list[dict]:
    return [
        {"id": "bw_fetch_repo_script", "num": 1, "title": "Download DVSwitch repo-install script",
         "cmd": _dv_fetch_repo_cmd("-O bookworm ")},
        {"id": "bw_run_repo_script", "num": 2, "title": "Run repo-install script (adds apt source + key)",
         "cmd": _dv_run_repo_cmd(), "note": _DV_REPO_NOTE},
        {"id": "bw_apt_update", "num": 3, "title": "Refresh package index", "cmd": "sudo apt update"},
        {"id": "bw_install_core", "num": 4, "title": "Install DVSwitch Server (base + Analog_Bridge + "
                                                       "md380-emu + MMDVM_Bridge)",
         "cmd": _DV_INSTALL_CMD, "timeout": 900, "note": _DV_INSTALL_NOTE},
        {"id": "bw_enable_services", "num": 5, "title": "Enable DVSwitch services at boot",
         "cmd": _DV_ENABLE_CMD, "note": _DV_ENABLE_NOTE},
        {"id": "bw_enable_gateways", "num": 6, "title": "Enable the digital-mode gateways at boot",
         "cmd": _DV_GATEWAYS_ENABLE_CMD, "note": _DV_GATEWAYS_NOTE},
        _dv_netcheck_step("bw_netcheck_safe", 7),
        _cockpit_install_step(8),
        _cockpit_enable_step(9),
        _dv_config_field_step(10),
        *_dv_web_clash_steps(11),
        _config_save_step("dv_save_restore", 13),
    ]

def _dvswitch_install_steps_trixie() -> list[dict]:
    return [
        {"id": "tx_preflight", "num": 1, "title": "Check what's already here (read-only)",
         "cmd": _DV_PREFLIGHT_CMD,
         "timeout": 30,
         "note": "Read-only — changes nothing. Shows the processor type, whether the DVSwitch package source is "
                 "set up, and for each working part whether its package is installed AND its program files are "
                 "actually present, plus which services exist. If everything shows installed / files present / "
                 "found, skip to step 7. There are no DVSwitch packages built for Debian 13 (Trixie), so this "
                 "path uses the official Bookworm repository — confirmed working on Trixie arm64 (652700, "
                 "2026-09-27); other processor types: run the step 5 test first."},
        {"id": "tx_fetch_repo_script", "num": 2, "title": "Download DVSwitch repo-install script",
         "cmd": _dv_fetch_repo_cmd("-O bookworm ")},
        {"id": "tx_run_repo_script", "num": 3, "title": "Run repo-install script (adds apt source + key)",
         "cmd": _dv_run_repo_cmd(), "note": _DV_REPO_NOTE},
        {"id": "tx_apt_update", "num": 4, "title": "Refresh package index", "cmd": "sudo apt update"},
        {"id": "tx_install_dryrun", "num": 5, "title": "Test install (changes nothing)",
         "cmd": f"apt-get install -s {_DV_COMPONENTS}",
         "timeout": 120,
         "note": "Safety gate. Simulates the install without changing anything. If this step FAILS or shows "
                 "'unmet dependencies', STOP — the packages don't fit this node and step 6 would fail too. "
                 "The first apt command after a lot of package changes can take a minute or two while apt "
                 "rebuilds its package list on the SD card; that is normal."},
        {"id": "tx_install_core", "num": 6, "title": "Install DVSwitch Server (base + Analog_Bridge + "
                                                    "md380-emu + MMDVM_Bridge)",
         "cmd": _DV_INSTALL_CMD, "timeout": 900, "note": "Only run after step 5 passed. " + _DV_INSTALL_NOTE},
        {"id": "tx_enable_services", "num": 7, "title": "Enable DVSwitch services at boot",
         "cmd": _DV_ENABLE_CMD, "note": _DV_ENABLE_NOTE},
        {"id": "tx_enable_gateways", "num": 8, "title": "Enable the digital-mode gateways at boot",
         "cmd": _DV_GATEWAYS_ENABLE_CMD, "note": _DV_GATEWAYS_NOTE},
        _dv_netcheck_step("tx_netcheck_safe", 9),
        _cockpit_install_step(10),
        _cockpit_enable_step(11),
        _dv_config_field_step(12),
        *_dv_web_clash_steps(13),
        _config_save_step("dv_save_restore", 15),
    ]

def _dvswitch_purge_steps_bookworm() -> list[dict]:
    return [
        {"id": "bw_purge_stop_services", "num": 1, "title": "Stop & disable DVSwitch services",
         "cmd": _DV_DISABLE_CMD,
         "note": "Stops and disables each DVSwitch service that exists and skips any that don't (a single "
                 "`systemctl disable a b c` aborts on the first missing one)."},
        {"id": "bw_purge_packages", "num": 2, "title": "Purge DVSwitch packages",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt purge -y dvswitch-server dvswitch dvswitch-base "
                "dvswitch-dashboard dvswitch-menu dvswitch-monit analog-bridge analog-reflector mmdvm-bridge "
                "md380-emu ircddbgateway",
         "note": "The bundle plus every DVSwitch package seen installed on a real node (652700): dvswitch, "
                 "dvswitch-base (netcheck), dvswitch-dashboard (runs on lighttpd), dvswitch-menu, dvswitch-monit "
                 "(a service monitor that auto-restarts DVSwitch services), the three working parts, and (v0.0.122) "
                 "analog-reflector + ircddbgateway, which dvswitch-server also pulls in -- analog-reflector was "
                 "missing here and its leftover mask broke a reinstall on 652700. apt skips names that aren't "
                 "installed; mosquitto is left to autoremove so it goes only if nothing else uses it."},
        {"id": "bw_purge_autoremove", "num": 3, "title": "Remove now-unused dependencies",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt autoremove -y --purge"},
        {"id": "bw_purge_repo", "num": 4, "title": "Remove the DVSwitch apt repository",
         "cmd": "sudo rm -f /etc/apt/sources.list.d/dvswitch*.list /etc/apt/trusted.gpg.d/dvswitch*.gpg "
                "/usr/share/keyrings/dvswitch*.gpg && sudo apt update",
         "note": "Best-effort — the dvswitch.org repo-install script adds its apt source directly rather than "
                 "via a named .deb, and doesn't publish its exact file paths, so this globs the common "
                 "locations. Verify with `apt policy` afterward that no dvswitch source remains."},
        {"id": "bw_purge_config", "num": 5, "title": "(Optional) Remove leftover node config",
         "cmd": "sudo rm -rf /opt/MMDVM_Bridge /opt/Analog_Bridge /opt/md380-emu /var/log/mmdvm /var/log/analog",
         "auto": False,
         "note": "NOT run automatically — deletes callsign/DMR ID/network credentials along with the "
                 "binaries and logs, which `apt purge` does not always remove on its own. Only run this for "
                 "a completely clean slate."},
        _cockpit_purge_step(6),
    ]

def _dvswitch_purge_steps_all() -> list[dict]:
    steps = [dict(s, id=s["id"].replace("bw_", "dv_", 1)) for s in _dvswitch_purge_steps_bookworm()]
    steps.insert(0, {"id": "dv_purge_netcheck_revert", "num": 1, "title": "Remove 44helper's netcheck and boot-order settings",
                     "pi_action": "dv_boot_undo", "button": "Remove them",
                     "note": "Removes the netcheck fixes and the DVSwitch boot-order drop-ins 44helper added (install "
                             "step 'Start DVSwitch after the network is ready', or tunnel step 6) so nothing is left "
                             "behind once the packages are gone. The tunnel's own boot settings stay. Does nothing if "
                             "none were added."})
    steps[1] = dict(steps[1], note=steps[1]["note"] + " This purge covers BOTH install options (Bookworm "
                                                     "and Trixie) -- it is the same list whichever is selected.")
    steps = [dict(st, num=i + 1) for i, st in enumerate(steps)]
    cockpit = steps.pop()
    steps.append({
        "id": "dv_purge_old_script_leftovers", "num": len(steps) + 1,
        "title": "(Optional) Remove leftovers from the old third-party build script",
        "cmd": "rm -f ~/install-dvswitch-trixie.sh; sudo rm -rf /tmp/MMDVM_Bridge /tmp/Analog_Bridge "
               "/tmp/md380-emu /tmp/bookworm; sudo rm -f /etc/systemd/system/analog_bridge.service "
               "/etc/systemd/system/mmdvm_bridge.service /etc/systemd/system/md380-emu.service && "
               "sudo systemctl daemon-reload",
        "auto": False,
        "note": "NOT run automatically. Only for nodes that ran the retired yo8aiv script (Trixie path before "
                "v0.0.101). The package installs its own units under /lib/systemd/system, so the "
                "/etc/systemd/system copies removed here would only be that script's (or your own hand "
                "overrides -- check first with ls /etc/systemd/system/*bridge* *emu*)."})
    steps.append(dict(cockpit, num=len(steps) + 1))
    return steps

_DVSWITCH_SCRIPTS: dict[str, dict[str, list[dict]]] = {
    "install": {"bookworm": _dvswitch_install_steps_bookworm(), "trixie": _dvswitch_install_steps_trixie()},
    "purge": {"bookworm": _dvswitch_purge_steps_all(), "trixie": _dvswitch_purge_steps_all()},
}

def _svx_config_field_step(num: int, conf_path: str = "/etc/svxlink/svxlink.conf",
                            svc: str = "svxlink") -> dict:
    return {
        "id": "configure_callsign", "num": num, "title": "Set Callsign",
        "fields": [
            {"id": "callsign", "label": "Callsign", "type": "text", "default": ""},
        ],
        "cmd_template": f"sudo sed -i 's/^CALLSIGN=.*/CALLSIGN={{{{callsign}}}}/' {conf_path} && "
                        f"sudo systemctl restart {svc}",
        "cmd": f"sudo sed -i 's/^CALLSIGN=.*/CALLSIGN=YOURCALL/' {conf_path} && "
               f"sudo systemctl restart {svc}",
        "note": "Best-effort in-place edit — matches on the key name (CALLSIGN=), not the existing value, so "
                "it works regardless of the installer's shipped placeholder. This only sets the callsign. "
                "The [SimplexLogic]/[RepeaterLogic] section inside this same svxlink.conf (not a separate "
                "file — svxlink.d/ only holds one config file per module, e.g. ModuleEchoLink.conf) also "
                "needs sound-card device and GPIO pin (PTT/COS) settings that are specific to your hardware — "
                "those are left as installer defaults; edit them by hand for your actual interface.",
    }

def _svxlink_install_steps() -> list[dict]:
    return [
        {"id": "svx_apt_update", "num": 1, "title": "Refresh package index", "cmd": "sudo apt update"},
        {"id": "svx_install_core", "num": 2, "title": "Install SvxLink Server",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt install -y "
                "-o Dpkg::Options::=\"--force-confdef\" -o Dpkg::Options::=\"--force-confold\" svxlink-server",
         "timeout": 900,
         "note": "svxlink-server is officially packaged in Debian's hamradio section for both Bookworm and "
                 "Trixie — no third-party repo needed here, unlike DVSwitch (dvswitch.org repo). Installs config "
                 "to /etc/svxlink, creates a dedicated 'svxlink' system user, and installs a systemd unit."},
        {"id": "svx_install_alsa_utils", "num": 3, "title": "Install ALSA utilities",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt install -y "
                "-o Dpkg::Options::=\"--force-confdef\" -o Dpkg::Options::=\"--force-confold\" alsa-utils"},
        {"id": "svx_user_groups", "num": 4, "title": "Add svxlink user to audio/serial groups",
         "cmd": "sudo usermod -a -G dialout,audio,plugdev svxlink",
         "note": "Needed for sound-card and USB-serial (COS/PTT) access on most USB interface setups — "
                 "harmless to run even if your interface doesn't need it. Takes effect on the service's next "
                 "start, not retroactively."},
        _svx_config_field_step(5),
        {"id": "svx_enable_service", "num": 6, "title": "Enable SvxLink at boot",
         "cmd": "sudo systemctl enable --now svxlink",
         "note": "The package may already enable this on install on some systems — this command is "
                 "idempotent either way."},
        _cockpit_install_step(7),
        _cockpit_enable_step(8),
    ]

_SVX_USRP_BUILD_DEPS = (
    "g++ cmake make libsigc++-2.0-dev libgsm1-dev libpopt-dev tcl-dev libgcrypt20-dev "
    "libspeex-dev libasound2-dev libopus-dev librtlsdr-dev doxygen groff alsa-utils "
    "vorbis-tools curl libcurl4-openssl-dev git rtl-sdr libjsoncpp-dev libgpiod-dev libssl-dev"
)

_SVX_USRP_PREFIX = "/usr/local"
_SVX_USRP_ETC = "/usr/local/etc/svxlink"
_SVX_USRP_SRC_DIR = "~/svxlink-usrp-src"

_SVX_USRP_LOGIC_SNIPPET = f"""# 1) {_SVX_USRP_ETC}/svxlink.conf -- in the [GLOBAL] section, change
#    LOGICS=SimplexLogic   to:
LOGICS=SimplexLogic,UsrpLogic

# 2) Same file -- add this section at the end, so the radio side and
#    the USRP side hear each other:
[LinkToUsrp]
CONNECT_LOGICS=SimplexLogic:9:USRP,UsrpLogic
DEFAULT_ACTIVE=1
TIMEOUT=0

# 3) {_SVX_USRP_ETC}/svxlink.d/UsrpLogic.conf -- change these lines:
DV_USER_INFOFILE={_SVX_USRP_ETC}/dv_users.json
CALL=YOURCALL
USRP_HOST=127.0.0.1
#    USRP_TX_PORT = the port Analog_Bridge LISTENS on (fork default 41234)
#    USRP_RX_PORT = the port Analog_Bridge SENDS to  (fork default 41233)
#    Match them to Analog_Bridge.ini -- the two ends are mirror images.
#    Keep everything on 127.0.0.1; never open these ports in a firewall."""

def _svxlink_install_steps_usrp() -> list[dict]:
    return [
        {"id": "usrp_preflight", "num": 1, "title": "Check for conflicts (read-only)",
         "cmd": "echo '--- apt package:'; st=$(dpkg-query -W -f='${Status}' svxlink-server 2>/dev/null); "
                "case \"$st\" in *not-installed*|'') echo '(not installed)';; *) echo \"$st\";; esac; "
                "echo '--- svxlink.service state:'; systemctl is-active svxlink 2>/dev/null; "
                "systemctl is-enabled svxlink 2>/dev/null; true",
         "note": "Read-only — changes nothing. This build installs under /usr/local (binaries in "
                 "/usr/local/bin, config in /usr/local/etc/svxlink) specifically so it can NOT collide with "
                 "an apt-installed svxlink-server's /usr and /etc files. It can still not RUN at the same "
                 "time as the apt package, though — same 'svxlink' service name and process, same default "
                 "ports. If the apt package shows installed/active above, stop and disable it first (Purge "
                 "on the package variant of this tab, or a manual systemctl stop/disable) before enabling "
                 "this build."},
        {"id": "usrp_deps", "num": 2, "title": "Install build dependencies",
         "cmd": "sudo apt update && sudo DEBIAN_FRONTEND=noninteractive apt install -y "
                "-o Dpkg::Options::=\"--force-confdef\" -o Dpkg::Options::=\"--force-confold\" "
                f"{_SVX_USRP_BUILD_DEPS}",
         "timeout": 900,
         "note": "Same dependency list as the official sm0svx source-build wiki (InstallSrcHwRpi) — the fork "
                 "is built on the same codebase, so the same build deps apply — plus libssl-dev (v0.0.139), "
                 "which newer SvxLink code needs and is harmless if unused."},
        {"id": "usrp_clone", "num": 3, "title": "Clone the USRP fork",
         "fields": [
             {"id": "branch", "label": "Branch", "type": "text", "default": "svxlink-usrp"},
         ],
         "cmd_template": f"rm -rf {_SVX_USRP_SRC_DIR} && "
                         "git clone --depth 1 -b {{branch}} https://github.com/dl1hrc/svxlink.git "
                         f"{_SVX_USRP_SRC_DIR}",
         "cmd": f"rm -rf {_SVX_USRP_SRC_DIR} && "
                f"git clone --depth 1 -b svxlink-usrp https://github.com/dl1hrc/svxlink.git {_SVX_USRP_SRC_DIR}",
         "note": "UNOFFICIAL, THIRD-PARTY fork (Adi Bier / DL1HRC) — not published or endorsed by the "
                 "SvxLink project. Adds a UsrpLogic module implementing the USRP protocol so SvxLink can "
                 "talk to the same DVSwitch Analog_Bridge/MMDVM_Bridge components this fleet's DVSwitch tab "
                 "installs. It is NOT merged upstream — see sm0svx/svxlink pull request #547 ('Svxlink usrp') "
                 "for the review discussion and current status. The branch name above ('svxlink-usrp') was "
                 "confirmed present on github.com/dl1hrc/svxlink on 2026-09-27 (an earlier default, 'usrp', "
                 "does not exist there; 'tetra-usrp' is a different project) — still re-check it before "
                 "running this step; forks get renamed or rebased without notice. Review the code yourself before trusting it on a production node. "
                 "Alternative (v0.0.140): f5vmr's svxlink_usrp script (github.com/f5vmr/svxlink_usrp) builds the same "
                 "fork, but it is documented for Bookworm only, asks for your callsign part-way through, and installs "
                 "into /usr and /etc — run it by hand in a terminal if you prefer it; it cannot run from this helper."},
        {"id": "usrp_build", "num": 4, "title": "Configure & build (compiles from source)",
         "cmd": "j=$(awk '/^MemAvailable:/ {print int($2/716800)}' /proc/meminfo); n=$(nproc); "
                "[ \"${j:-0}\" -lt 1 ] && j=1; [ \"$j\" -gt \"$n\" ] && j=$n; "
                f"cd {_SVX_USRP_SRC_DIR}/src && "
                "if ! grep -rqs --include=CMakeLists.txt --include='*.cmake' WITH_CONTRIB_USRP_LOGIC . ; then "
                "echo 'STOP: this copy of the fork has no WITH_CONTRIB_USRP_LOGIC build switch -- the USRP part "
                "would not be built. Check the branch name in step 3.'; exit 1; fi && "
                "echo 'USRP build switch found in the fork -- building with it on.' && "
                "mkdir -p build && cd build && "
                "cmake -DUSE_QT=OFF -DCMAKE_BUILD_TYPE=Release -DWITH_CONTRIB_USRP_LOGIC=ON "
                f"-DCMAKE_INSTALL_PREFIX={_SVX_USRP_PREFIX} "
                f"-DSYSCONF_INSTALL_DIR={_SVX_USRP_PREFIX}/etc -DLOCAL_STATE_DIR=/var .. && "
                "echo \"Building with $j parallel job(s) (free memory / 700 MB, max $n)\" && "
                "make -j$j && sudo make install && sudo ldconfig",
         "timeout": None,
         "note": "Compiles the full SvxLink suite (svxlink, remotetrx, and the rest) plus UsrpLogic from "
                 "source. v0.0.139: runs from the fork's src/ folder (where SvxLink keeps its build file) with "
                 "-DWITH_CONTRIB_USRP_LOGIC=ON — the switch that turns on the USRP part — and first checks the "
                 "fork really has that switch, stopping if not (cmake alone would only warn and quietly build "
                 "without USRP). v0.0.155: -DSYSCONF_INSTALL_DIR is /usr/local/etc -- the build adds "
                 "'/svxlink' itself (src/CMakeLists.txt), so the config lands in /usr/local/etc/svxlink "
                 "(before, it went to /usr/local/etc/svxlink/svxlink and the later steps missed it). Parallel "
                 "jobs are limited by free memory (one per 700 MB) so the 512 MB Pi Zero 2W builds with one "
                 "job instead of running out of memory. This runs with no timeout since a full SvxLink build reliably takes well over the "
                 "5-10 minutes a small single-program build takes, and can run "
                 "far longer than that on the Pi Zero 2W travel node (652702). SECURITY: a PR reviewer "
                 "(MarkRose) found UsrpLogic's UDP message unpacker throws on a crafted datagram under 32 "
                 "bytes with no surrounding try/catch — a single malformed packet can crash the process — "
                 "and this was still unpatched as of the last review on PR #547. Keep whatever UDP port this "
                 "logic listens on bound to 127.0.0.1 only; do NOT add it to a firewalld zone or route it "
                 "over the WireGuard tunnel (same loopback-only handling the Ports tab and the tunnel tabs' firewall cards already use "
                 "for the DVSwitch/M17 USRP channels). BENCH-ONLY: this tool cannot exercise an actual build "
                 "of a third-party fork in its own sandbox — confirm the build completes and installs "
                 "cleanly on real hardware (652702/652703) before relying on it."},
        {"id": "usrp_check_built", "num": 5, "title": "Check the USRP part was built (read-only)",
         "cmd": f"f=$(find {_SVX_USRP_PREFIX}/lib {_SVX_USRP_PREFIX}/share/svxlink {_SVX_USRP_ETC} "
                "-iname '*usrp*' 2>/dev/null); "
                "if [ -n \"$f\" ]; then echo 'USRP part: FOUND'; echo \"$f\"; "
                f"echo; echo 'USRP settings file: {_SVX_USRP_ETC}/svxlink.d/UsrpLogic.conf'; "
                f"ls -l {_SVX_USRP_ETC}/svxlink.d/ 2>/dev/null | grep -i usrp || "
                "echo '(no UsrpLogic.conf there yet -- check the list above for where the template landed)'; "
                "else echo 'USRP part: NOT FOUND -- the build finished without it. Re-run steps 3 and 4 and read "
                "step 4 output for the USRP switch line.'; exit 1; fi",
         "timeout": 60,
         "note": "Read-only. Confirms the build really included the USRP part (a build without it still "
                 "'succeeds', which is why this is checked on its own). For this build the USRP settings live in "
                 "/usr/local/etc/svxlink/svxlink.d/UsrpLogic.conf — not /etc/svxlink/..., which is where "
                 "guides that install into /usr put it. Port matching: the port SvxLink SENDS to must be the port "
                 "Analog_Bridge LISTENS on, and the port SvxLink listens on must be the one Analog_Bridge sends "
                 "to — the two ends are mirror images. Keep both on 127.0.0.1. Use the key names in the template "
                 "the build installed, not ones copied from a web page."},
        {"id": "usrp_user", "num": 6, "title": "Create the svxlink user",
         "cmd": "if id svxlink >/dev/null 2>&1; then echo 'svxlink user already exists'; "
                "elif getent group svxlink >/dev/null; then sudo useradd -r -g svxlink -d /var/lib/svxlink "
                "-s /usr/sbin/nologin svxlink && echo 'svxlink user created'; "
                "else sudo useradd -r -U -d /var/lib/svxlink -s /usr/sbin/nologin svxlink && "
                "echo 'svxlink user created'; fi && "
                "sudo usermod -a -G dialout,audio,plugdev svxlink && "
                "sudo mkdir -p /var/spool/svxlink /var/lib/svxlink && "
                "sudo chown -R svxlink:svxlink /var/spool/svxlink /var/lib/svxlink && "
                "sudo touch /var/log/svxlink && sudo chown svxlink:svxlink /var/log/svxlink && "
                "id svxlink",
         "timeout": 60,
         "note": "Safe to run more than once. A source build doesn't create the 'svxlink' user the way the apt "
                 "package does, and the service in step 9 runs as that user. Also adds it to the sound-card and "
                 "USB-serial groups, and makes its log file, spool and state folders writable by it — without that, the "
                 "service would fail to start as svxlink."},
        {"id": "usrp_locate", "num": 7, "title": "Locate installed files (read-only)",
         "cmd": f"which svxlink; ls -la {_SVX_USRP_ETC} 2>/dev/null; "
                f"find {_SVX_USRP_PREFIX} -iname 'svxlink*.service' 2>/dev/null; true",
         "note": "Read-only. A third-party fork's CMakeLists can differ from upstream's — this lists what "
                 "the build step actually installed and where, since step 9 (manual) needs the real "
                 "binary path to write a correct systemd unit."},
        {"id": "usrp_logic_conf", "num": 8, "title": "svxlink.conf + UsrpLogic.conf — switch UsrpLogic on",
         "manual": True, "manual_block": True,
         "cmd": _SVX_USRP_LOGIC_SNIPPET,
         "note": "Edit by hand (nano or the Cockpit file editor) — v0.0.155. The build installs UsrpLogic but "
                 "does not switch it on: svxlink.conf ships with LOGICS=SimplexLogic and no link to it, so "
                 "without these edits the service starts but no audio reaches the USRP side. Change "
                 "SimplexLogic to RepeaterLogic below if that is the logic your node uses. The "
                 "DV_USER_INFOFILE fix is needed because the fork's template points at /etc/svxlink, but "
                 "this build installs that file under /usr/local/etc/svxlink."},
        {"id": "usrp_service_unit", "num": 9, "title": "Systemd unit (author by hand)", "manual": True,
         "manual_block": True,
         "cmd": "[Unit]\nDescription=SvxLink (USRP fork)\nAfter=network.target sound.target\n\n[Service]\n"
                f"ExecStart={_SVX_USRP_PREFIX}/bin/svxlink --logfile=/var/log/svxlink --config={_SVX_USRP_ETC}/svxlink.conf\n"
                "User=svxlink\nRestart=on-failure\n\n[Install]\nWantedBy=multi-user.target",
         "note": "Too risky to guess-and-write onto a live system unattended (same reasoning the M17 tab "
                 "uses for its rpt.conf/modules.conf edits). Adjust the ExecStart path above using step 5's "
                 "output if it differs, save this as /etc/systemd/system/svxlink-usrp.service, then run "
                 "`sudo systemctl daemon-reload && sudo systemctl enable --now svxlink-usrp` yourself. The "
                 "'svxlink' user it runs as comes from step 6 — run that first. Do step 8 (UsrpLogic on, "
                 "ports) before starting it."},
        _svx_config_field_step(10, conf_path=f"{_SVX_USRP_ETC}/svxlink.conf", svc="svxlink-usrp"),
        _cockpit_install_step(11),
        _cockpit_enable_step(12),
    ]

def _svxlink_purge_steps_usrp() -> list[dict]:
    return [
        {"id": "usrp_purge_stop", "num": 1, "title": "Stop & disable svxlink-usrp",
         "cmd": "sudo systemctl disable --now svxlink-usrp 2>&1; true",
         "note": "Trailing `; true` so this doesn't report failure if the unit was never installed."},
        {"id": "usrp_purge_binaries", "num": 2, "title": "(Optional) Remove compiled binaries and config",
         "cmd": f"m={_SVX_USRP_SRC_DIR}/src/build/install_manifest.txt; "
                "if [ -f \"$m\" ]; then echo \"Removing the $(wc -l < \"$m\") files the build installed "
                "(from $m)\"; tr '\\n' '\\0' < \"$m\" | sudo xargs -0 rm -f --; "
                "else echo 'No install list from the build -- removing the known paths instead'; "
                f"sudo rm -f {_SVX_USRP_PREFIX}/bin/svxlink {_SVX_USRP_PREFIX}/bin/remotetrx "
                f"{_SVX_USRP_PREFIX}/bin/svxreflector {_SVX_USRP_PREFIX}/bin/siglevdetcal "
                f"{_SVX_USRP_PREFIX}/bin/devcal; fi; "
                f"sudo rm -rf {_SVX_USRP_PREFIX}/lib/svxlink {_SVX_USRP_PREFIX}/lib/*/svxlink {_SVX_USRP_ETC} "
                f"{_SVX_USRP_PREFIX}/share/svxlink && sudo ldconfig",
         "auto": False,
         "note": "NOT run automatically — there's no apt package to purge for a source build. v0.0.155: "
                 "removes every file the build installed (its own install list, build/install_manifest.txt, "
                 "so svxreflector, the shared libraries and man pages go too), falling back to the "
                 "well-known paths if the source folder is gone, and deletes the callsign/config along with it. Only run this for a completely "
                 "clean slate; double-check nothing else under /usr/local depends on these paths first."},
        {"id": "usrp_purge_unit", "num": 3, "title": "(Optional) Remove the hand-authored systemd unit",
         "cmd": "sudo rm -f /etc/systemd/system/svxlink-usrp.service && sudo systemctl daemon-reload",
         "auto": False,
         "note": "Only removes it if you saved it at the path suggested in the install step's manual card."},
        {"id": "usrp_purge_source", "num": 4, "title": "(Optional) Remove cloned source tree",
         "cmd": f"rm -rf {_SVX_USRP_SRC_DIR}",
         "auto": False,
         "note": "NOT run automatically — matches this variant's rule that purge only auto-runs the "
                 "service stop. Keeping the source tree lets you rebuild without re-cloning."},
    ]

def _svxlink_purge_steps() -> list[dict]:
    return [
        {"id": "svx_purge_stop", "num": 1, "title": "Stop & disable SvxLink",
         "cmd": "sudo systemctl disable --now svxlink 2>&1; true",
         "note": "Trailing `; true` so this doesn't report failure if the unit was never installed."},
        {"id": "svx_purge_packages", "num": 2, "title": "Purge SvxLink package",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt purge -y svxlink-server"},
        {"id": "svx_purge_autoremove", "num": 3, "title": "Remove now-unused dependencies",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt autoremove -y --purge"},
        {"id": "svx_purge_config", "num": 4, "title": "(Optional) Remove leftover node config",
         "cmd": "sudo rm -rf /etc/svxlink /var/spool/svxlink",
         "auto": False,
         "note": "NOT run automatically — deletes callsign, GPIO pin, and sound-card settings along with "
                 "the config, which `apt purge` does not always remove on its own (Debian conffiles are "
                 "often left in place). Only run this for a completely clean slate."},
        _cockpit_purge_step(5),
    ]

def _svxlink_purge_steps_all() -> list[dict]:
    usrp = {st["id"]: st for st in _svxlink_purge_steps_usrp()}
    pkg = {st["id"]: st for st in _svxlink_purge_steps()}
    steps = [
        {"id": "svx_purge_stop", "title": "Stop & disable SvxLink (package and USRP build)",
         "cmd": "for u in svxlink svxlink-usrp; do sudo systemctl disable --now \"$u\" 2>&1; done; true",
         "note": "Stops whichever of the two services exists. Trailing `true` so a service that was never "
                 "installed isn't reported as a failure. This purge covers ALL THREE install options "
                 "(Bookworm, Trixie, USRP fork) -- it is the same list whichever is selected."},
        {"id": "svx_purge_packages", "title": "Purge SvxLink package (if present)",
         "cmd": "st=$(dpkg-query -W -f='${Status}' svxlink-server 2>/dev/null); case \"$st\" in "
                "*not-installed*|'') echo 'svxlink-server package not on this node -- skipped.';; "
                "*) sudo DEBIAN_FRONTEND=noninteractive apt purge -y svxlink-server;; esac",
         "note": "Only runs apt purge if dpkg knows the package (installed, half-installed, or settings left "
                 "behind). A USRP-build-only node skips this cleanly."},
        dict(pkg["svx_purge_autoremove"]),
        dict(pkg["svx_purge_config"], title="(Optional) Remove leftover node config (package install)"),
        dict(usrp["usrp_purge_binaries"], title="(Optional) Remove USRP build binaries and config (/usr/local)"),
        dict(usrp["usrp_purge_unit"]),
        dict(usrp["usrp_purge_source"],
             note="NOT run automatically. Keeping the source folder lets you rebuild without re-cloning."),
        _cockpit_purge_step(0),
    ]
    for i, st in enumerate(steps, 1):
        st["num"] = i
    return steps

_SVXLINK_SCRIPTS: dict[str, dict[str, list[dict]]] = {
    "install": {"bookworm": _svxlink_install_steps(), "trixie": _svxlink_install_steps(),
                "usrp": _svxlink_install_steps_usrp()},
    "purge": {"bookworm": _svxlink_purge_steps_all(), "trixie": _svxlink_purge_steps_all(),
              "usrp": _svxlink_purge_steps_all()},
}

_M17_RPTCONF_SNIPPET = """[1917]
   rxchannel = USRP/127.0.0.1:34008:32008  ; USRP channel driver — must be enabled in modules.conf
     ; 127.0.0.1 = IP of the target application
     ; 34008 = UDP port the target application (USRP2M17) is listening on
     ; 32008 = UDP port Asterisk/ASL is listening on
   duplex = 0
   hangtime = 0
   althangtime = 0
   holdofftelem = 1
   telemdefault = 0
   telemdynamic = 0
   linktolink = no
   nounkeyct = 1
   tx_timeout = 170000
;END OF NODE 1917

[nodes]
; add this line alongside your existing node entry — do not remove
; anything else already in this stanza
1917 = radio@127.0.0.1/1917,NONE  ; M17 node
"""

_M17_MODULES_SNIPPET = """In /etc/asterisk/modules.conf, change:

  noload=chan_usrp.so

to:

  load=chan_usrp.so
"""

_M17_EXTENSIONS_SNIPPET = """Add to the [radio-secure] stanza in /etc/asterisk/extensions.conf:

exten => 1917,1,rpt,1917

ASL3-specific (community-reported by the upstream README, not confirmed
by an official AllStarLink doc) — also add to rpt.conf's own [globals]
stanza:

NODE1 = 1917
"""

def _m17_install_steps() -> list[dict]:
    return [
        {"id": "m17_install_git", "num": 1, "title": "Install git",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt update && "
                "sudo DEBIAN_FRONTEND=noninteractive apt install -y "
                "-o Dpkg::Options::=\"--force-confdef\" -o Dpkg::Options::=\"--force-confold\" git"},
        {"id": "m17_install_php", "num": 2, "title": "Install PHP for Apache",
         "cmd": "sudo DEBIAN_FRONTEND=noninteractive apt install -y "
                "-o Dpkg::Options::=\"--force-confdef\" -o Dpkg::Options::=\"--force-confold\" "
                "php libapache2-mod-php",
         "note": "ASL3-Appliance already ships apache2 on most nodes (pulled in by asl3-appliance-pi's "
                 "fallback-AP feature — see the v0.0.30 note). libapache2-mod-php normally enables itself "
                 "via its own postinst hook; if PHP still doesn't execute afterward, check "
                 "`apache2ctl -M | grep php` and run `sudo a2enmod php<version>` by hand for whatever PHP "
                 "version apt installed. Kept together as one step (not split further) since both packages "
                 "jointly exist for the one purpose of running the installer's PHP web UI — unlike git, "
                 "which serves an unrelated purpose (fetching the repo)."},
        {"id": "m17_clone", "num": 3, "title": "Clone USRP2M17-Selector",
         "cmd": "cd /tmp && rm -rf USRP2M17-Selector && "
                "git -c http.version=HTTP/1.1 clone --depth 1 https://github.com/mjwgeek/USRP2M17-Selector.git && "
                "cd USRP2M17-Selector && chmod +x install.sh",
         "note": "Upstream is licensed No-Modification/No-Redistribution, personal/non-commercial use only — "
                 "this step only fetches their own unmodified files to run locally, the same as a manual "
                 "`git clone`. Nothing from the repo is copied into this tool. Uses --depth 1 (no history "
                 "needed for a small repo you're just running install.sh from) and forces HTTP/1.1 for this "
                 "one command only (via -c, not --global) — a live test hit a mid-transfer HTTP/2 stream "
                 "cancellation on a flaky connection; both changes make the clone more likely to survive a "
                 "marginal link without touching git's global config."},
        {"id": "m17_run_install", "num": 4, "title": "Run the installer (prompts for callsign)",
         "cmd": "cd /tmp/USRP2M17-Selector && sudo ./install.sh",
         "manual": True,
         "note": "INTERACTIVE — install.sh prompts for your callsign and does the real install (PHP UI to "
                 "/var/www/html/m17, a usrp2m17.service unit, directory permissions). This engine has no "
                 "stdin channel to answer prompts, same reasoning as the ASL3 tab's asl-menu step — run this "
                 "over SSH or the Cockpit terminal instead."},
        {"id": "m17_rptconf", "num": 5, "title": "rpt.conf — add the M17 node stanza",
         "cmd": _M17_RPTCONF_SNIPPET,
         "manual_block": True,
         "note": "Edit /etc/asterisk/rpt.conf by hand (nano or the Cockpit file editor) — add this stanza "
                 "plus the matching [nodes] line. 1917 is upstream's example node number; change it to "
                 "whatever number you want to dedicate to M17 traffic. Edit the text below before copying if "
                 "you want a different node number."},
        {"id": "m17_modules", "num": 6, "title": "modules.conf — enable chan_usrp",
         "cmd": _M17_MODULES_SNIPPET,
         "manual_block": True,
         "note": "Edit /etc/asterisk/modules.conf by hand — flips the USRP channel driver from unloaded to "
                 "loaded, required for the rpt.conf rxchannel line above to work."},
        {"id": "m17_extensions", "num": 7, "title": "extensions.conf — add the M17 extension",
         "cmd": _M17_EXTENSIONS_SNIPPET,
         "manual_block": True,
         "note": "Edit /etc/asterisk/extensions.conf by hand. The ASL3 globals addition is community-"
                 "reported in the upstream README (\"is it correct? I don't know but it worked for me\"), not "
                 "an officially documented requirement — include it if your ASL3 config uses NODE/NODE1 "
                 "globals elsewhere, skip it otherwise."},
        {"id": "m17_restart_asterisk", "num": 8, "title": "Restart Asterisk",
         "cmd": "sudo astres.sh",
         "note": "astres.sh is ASL3/HamVOIP's standard Asterisk-restart helper. If it's not on PATH on your "
                 "image, edit this field to `sudo systemctl restart asterisk` before running."},
        _config_save_step("m17_save_restore", 9),
        {"id": "m17_sudoers", "num": 10, "title": "Install sudoers rule for the web UI",
         "cmd": "printf 'www-data ALL=(ALL) NOPASSWD: /var/www/html/m17/update_usrp2m17.sh\\n"
                "www-data ALL=(ALL) NOPASSWD: /bin/systemctl restart usrp2m17\\n' | "
                "sudo tee /etc/sudoers.d/usrp2m17 >/dev/null && "
                "sudo chmod 0440 /etc/sudoers.d/usrp2m17 && "
                "sudo visudo -c -f /etc/sudoers.d/usrp2m17",
         "note": "Uses a dedicated /etc/sudoers.d/ drop-in (validated with `visudo -c` before it takes "
                 "effect) instead of hand-editing /etc/sudoers via visudo like the upstream README shows — "
                 "a drop-in is safer to install/remove unattended. Assumes ASL3-Appliance's Apache runs as "
                 "www-data; if this node is HamVOIP instead (runs its web server as `http`), edit the "
                 "installed file afterward and swap www-data for http, matching upstream's HamVOIP block."},
        _cockpit_install_step(11),
        _cockpit_enable_step(12),
    ]

def _m17_purge_steps() -> list[dict]:
    return [
        {"id": "m17_purge_stop", "num": 1, "title": "Stop & disable USRP2M17",
         "cmd": "sudo systemctl disable --now usrp2m17 2>&1; true",
         "note": "Trailing `; true` so this doesn't report failure if the unit was never installed."},
        {"id": "m17_purge_webroot", "num": 2, "title": "Remove the web UI",
         "cmd": "sudo rm -rf /var/www/html/m17"},
        {"id": "m17_purge_sudoers", "num": 3, "title": "Remove the sudoers drop-in",
         "cmd": "sudo rm -f /etc/sudoers.d/usrp2m17"},
        {"id": "m17_purge_unit", "num": 4, "title": "Remove the systemd unit",
         "cmd": "sudo rm -f /etc/systemd/system/usrp2m17.service && sudo systemctl daemon-reload",
         "note": "Best-effort filename, taken from the repo's usrp2m17.service file — confirm with "
                 "`systemctl status usrp2m17` first if unsure it matches what install.sh actually wrote."},
        {"id": "m17_purge_clone_dir", "num": 5, "title": "(Optional) Remove the clone directory",
         "cmd": "sudo rm -rf /tmp/USRP2M17-Selector",
         "auto": False,
         "note": "NOT run automatically — harmless leftover clone-directory cleanup only. Separately: the "
                 "rpt.conf / modules.conf / extensions.conf edits from the install steps above are NEVER "
                 "reverted by purge — remove the M17 stanza/lines and restore noload=chan_usrp.so by hand, "
                 "then restart Asterisk, if you want a completely clean slate."},
        _cockpit_purge_step(6),
    ]

_M17_SCRIPTS: dict[str, dict[str, list[dict]]] = {
    "install": {"standard": _m17_install_steps()},
    "purge": {"standard": _m17_purge_steps()},
}

def _m17_lookup_step(mode: str, distro: str, step_id: str) -> dict | None:
    for step in _M17_SCRIPTS.get(mode, {}).get(distro, []):
        if step["id"] == step_id:
            return step
    return None

