def _cf_token_install_steps() -> list[dict]:
    return [
        _cf_preflight_step(),
        _cf_install_apt_step(),
        {"id": "cf_svc_install", "num": 3, "title": "Install the connector service (paste the token by hand)",
         "cmd": _CF_TOKEN_INSTALL_BLOCK,
         "manual_block": True,
         "note": "MANUAL / not run through this engine -- on purpose. Copy the whole `sudo cloudflared service "
                 "install eyJ...` command from your tunnel in the Zero Trust dashboard (Networks -> Connectors -> "
                 "Cloudflare Tunnels -> your tunnel) and run it over SSH. Running it here would write the token "
                 "into the Actions Log; running it by hand keeps it out. cloudflared still stores the token at "
                 "rest in the service unit / /etc/cloudflared by design -- it is dashboard-regenerable, so that is "
                 "acceptable. This installs and starts cloudflared.service."},
        {"id": "cf_verify", "num": 4, "title": "Verify the connector (read-only)",
         "cmd": "sudo systemctl status cloudflared --no-pager || true; "
                "journalctl -u cloudflared -n 30 --no-pager",
         "timeout": 30,
         "note": "Read-only. Confirm the service is active and, in the Zero Trust dashboard, that the connector "
                 "shows Healthy. Deliberately NOT `cloudflared tunnel list` -- that needs a local cert the token "
                 "method never creates."},
        {"id": "cf_dash_note", "num": 5, "title": "Map a Public Hostname + add an Access policy (dashboard)",
         "cmd": _CF_DASH_NEXT_STEPS_URL,
         "manual": True,
         "note": "No command to run here. In the Zero Trust dashboard, open your tunnel's Public Hostname tab and "
                 "map a hostname to the LOCAL service you want reachable (e.g. http://localhost:8989 for the "
                 "dashboard, :9999 sysmon, :8990 instmon, or this 44helper's port). SECURITY: a Cloudflare Tunnel "
                 "needs no inbound port, so the firewall and the Ports tab can't see or flag what it publishes. Only tunnel a "
                 "service that has its own auth, and/or put a Cloudflare Access policy in front of the hostname "
                 "(same dashboard) before exposing anything -- the dashboard 8989 and sysmon 9999 share one "
                 "root-password login, which is thin cover on the open internet, and instmon's auth is opt-in."},
    ]

def _cf_token_purge_steps() -> list[dict]:
    return [
        {"id": "cf_purge_uninstall", "num": 1, "title": "Uninstall the connector service",
         "cmd": "sudo cloudflared service uninstall 2>&1; true",
         "note": "Stops, disables and removes cloudflared.service. Trailing `; true` so this doesn't report "
                 "failure if no service was installed. The web-managed tunnel itself is removed from the Zero "
                 "Trust dashboard, NOT from this host (there is no `cloudflared tunnel delete` for token mode)."},
        {"id": "cf_purge_pkg", "num": 2, "title": "Remove the cloudflared package",
         "cmd": "sudo apt-get purge -y cloudflared 2>&1; true"},
        {"id": "cf_purge_creds", "num": 3, "title": "(Optional) Remove stored credentials",
         "cmd": "sudo rm -rf /etc/cloudflared",
         "auto": False,
         "note": "NOT run automatically -- deletes the stored connector token / credentials under "
                 "/etc/cloudflared. Only run this for a completely clean slate. The token is regenerable in the "
                 "Zero Trust dashboard, so this is safe/reversible."},
    ]

