_PURGE_CLEANUP_SPEC: dict[str, tuple[str, list[str]]] = {
    "asl3": ("^(asl3|allmon3|asterisk)", ["/etc/asterisk", "/var/lib/asterisk", "/etc/allmon3"]),
    "dv": ("^(dvswitch|analog-bridge|analog-reflector|mmdvm-bridge|md380-emu|ircddbgateway)",
           ["/opt/MMDVM_Bridge", "/opt/Analog_Bridge", "/opt/md380-emu", "/opt/Analog_Reflector",
            "/var/lib/dvswitch", "/var/log/dvswitch", "/var/log/mmdvm", "/etc/monit/conf.d/monitrc"]),
    "svx": ("^(svxlink|remotetrx|qtel)", ["/etc/svxlink", "/usr/local/etc/svxlink", "/usr/share/svxlink"]),
    "m17": ("^(usrp2m17|m17)", ["/opt/USRP2M17"]),
    "amp": ("^amp-", []),
    "cf": ("^cloudflared", ["/etc/cloudflared"]),
}

def _purge_cleanup_steps(tab: str) -> list[dict]:
    regex, dirs = _PURGE_CLEANUP_SPEC[tab]
    units = " ".join(_GUARD_TAB_UNITS[tab])
    rc_cmd = ("pk=$(dpkg -l 2>/dev/null | awk '/^rc/ {print $2}' | grep -E '" + regex + "' || true); "
              "if [ -z \"$pk\" ]; then echo 'No removed-but-not-purged packages for this tab.'; "
              "else echo \"Purging leftovers: $pk\"; "
              "sudo DEBIAN_FRONTEND=noninteractive apt purge -y $pk; fi")
    unmask_cmd = ("n=0; for u in " + units + "; do s=$(systemctl is-enabled \"$u\" 2>/dev/null); case \"$s\" in "
                  "masked) sudo systemctl unmask \"$u\" && echo \"unmasked $u\" && n=$((n+1));; "
                  "masked-runtime) sudo systemctl unmask --runtime \"$u\" && echo \"unmasked $u\" && n=$((n+1));; "
                  "esac; done; echo \"$n masked service(s) of this tab cleared.\"; true")
    links_cmd = ("n=0; for u in " + units + "; do for l in $(find /etc/systemd/system -xtype l -name \"$u\" "
                 "2>/dev/null); do sudo rm -f \"$l\" && echo \"removed broken link $l\" && n=$((n+1)); done; done; "
                 "if [ $n -gt 0 ]; then sudo systemctl daemon-reload; fi; echo \"$n broken link(s) removed.\"; true")
    report_cmd = ("echo '--- packages still present:'; "
                  "dpkg -l 2>/dev/null | awk '$1 ~ /^(ii|rc|iU|iF|iH|iW|it)$/ {print $2\" (\"$1\")\"}' | grep -E '"
                  + regex + "' || echo '(none)'; "
                  "echo '--- masked:'; m=0; for u in " + units + "; do case \"$(systemctl is-enabled \"$u\" 2>/dev/null)\" "
                  "in masked*) echo \"$u\"; m=1;; esac; done; [ $m -eq 0 ] && echo '(none)'; "
                  "echo '--- service files left in /etc/systemd/system:'; f=0; for u in " + units + "; do "
                  "if [ -e \"/etc/systemd/system/$u\" ] || [ -L \"/etc/systemd/system/$u\" ]; then "
                  "ls -l \"/etc/systemd/system/$u\"; f=1; fi; done; [ $f -eq 0 ] && echo '(none)'; "
                  "echo '--- folders:'; d=0; for p in " + (" ".join(dirs) if dirs else "") + "; do "
                  "if [ -e \"$p\" ]; then echo \"$p\"; d=1; fi; done; [ $d -eq 0 ] && echo '(none)'; true")
    return [
        {"id": f"{tab}_cleanup_rc", "num": 0, "title": "Clean up: purge this tab's removed-but-not-purged packages",
         "cmd": rc_cmd,
         "note": "Packages removed without purge keep their config AND the masks their removal put on their own "
                 "services -- which then break the next install. This finishes the purge for this tab's packages only."},
        {"id": f"{tab}_cleanup_unmask", "num": 0, "title": "Clean up: unmask this tab's own services",
         "cmd": unmask_cmd,
         "note": "Only this tab's own services. Debian's intentional masks (sudo, hwclock, cryptdisks, x11-common, "
                 "alsa-utils) are never touched."},
        {"id": f"{tab}_cleanup_links", "num": 0, "title": "Clean up: remove broken boot links for this tab's services",
         "cmd": links_cmd},
        {"id": f"{tab}_cleanup_report", "num": 0, "title": "Still left behind (read-only report)",
         "cmd": report_cmd, "timeout": 60,
         "note": "Changes nothing. Lists what is still on the node for this tab after the purge -- packages, "
                 "masks, service files, folders -- so nothing is left behind silently."},
    ]

def _add_purge_cleanup() -> None:
    seen = set()
    for tab, catalog in (("asl3", _ASL3_SCRIPTS), ("dv", _DVSWITCH_SCRIPTS), ("svx", _SVXLINK_SCRIPTS),
                         ("m17", _M17_SCRIPTS), ("amp", _AMP_SCRIPTS), ("cf", _CF_SCRIPTS)):
        for distro, steps in catalog["purge"].items():
            if id(steps) in seen:
                continue
            seen.add(id(steps))
            at = next((i for i, st in enumerate(steps) if st.get("auto") is False or st.get("manual")), len(steps))
            steps[at:at] = _purge_cleanup_steps(tab)
            for i, st in enumerate(steps, 1):
                st["num"] = i

_add_purge_cleanup()

_TERM_ENABLE_FILE = CONFIG_DIR / "terminal.enable"
_TERM_ALLOW: dict[str, tuple[str, str]] = {
    "asl_menu": ("run_asl_menu", "asl-menu (ASL3 node settings)"),
    "m17_install": ("m17_run_install", "USRP2M17 installer (asks for your callsign)"),
    "amp_firstrun": ("amp_srv_firstrun", "amp-server first run (foreground)"),
}
_TERM_PROXY_HEADERS = ("Cf-Connecting-Ip", "Cf-Ray", "Cf-Ipcountry", "Cf-Visitor", "X-Forwarded-For",
                       "X-Forwarded-Host", "X-Forwarded-Proto", "X-Real-Ip", "Forwarded", "Via")
_TERM_TICKET_TTL = 60.0
_TERM_TICKETS: dict[str, dict] = {}
_TERM_LOCK = threading.Lock()

def _term_allowlist() -> dict[str, dict]:
    out: dict[str, dict] = {}
    catalogs = (_ASL3_SCRIPTS, _DVSWITCH_SCRIPTS, _SVXLINK_SCRIPTS, _M17_SCRIPTS, _AMP_SCRIPTS, _CF_SCRIPTS)
    for tid, (step_id, title) in _TERM_ALLOW.items():
        cmds = {st.get("cmd") for cat in catalogs for steps in cat.get("install", {}).values()
                for st in steps if st.get("id") == step_id and st.get("cmd")}
        if len(cmds) == 1:
            out[tid] = {"id": tid, "step": step_id, "title": title, "cmd": cmds.pop()}
    return out

def _term_enabled() -> tuple[bool, str]:
    try:
        st = os.stat(_TERM_ENABLE_FILE)
    except FileNotFoundError:
        return False, (f"The terminal is switched off. To switch it on, run this on the node itself: "
                       f"sudo touch {_TERM_ENABLE_FILE}")
    except OSError as exc:
        return False, f"Could not check {_TERM_ENABLE_FILE}: {exc}"
    if not stat.S_ISREG(st.st_mode):
        return False, f"{_TERM_ENABLE_FILE} must be a plain file."
    if st.st_uid != 0 or st.st_mode & 0o022:
        return False, f"{_TERM_ENABLE_FILE} must be owned by root and not writable by anyone else."
    return True, ""

def _term_client_ok(ip: str, headers) -> tuple[bool, str]:
    for h in _TERM_PROXY_HEADERS:
        if headers.get(h) is not None:
            return False, ("Refused: this request came through a proxy or tunnel (for example Cloudflare). "
                           "The terminal only works from your local network.")
    try:
        addr = ipaddress.ip_address(ip)
    except ValueError:
        return False, "Refused: could not read the address this request came from."
    mapped = getattr(addr, "ipv4_mapped", None)
    if mapped is not None:
        addr = mapped
    if addr.is_loopback or addr.is_link_local or addr.is_private:
        return True, ""
    return False, f"Refused: {addr} is not a local-network address. The terminal only works from your LAN."

def _term_can_enable(ip: str, headers) -> tuple[bool, str]:
    ok, why = _term_client_ok(ip, headers)
    if not ok:
        return False, why
    if os.geteuid() != 0:
        return False, (f"44helper is not running as root, so it cannot switch the terminal on. Run this on "
                       f"the node instead: sudo touch {_TERM_ENABLE_FILE}")
    return True, ""

def _term_switch(on: bool, ip: str) -> tuple[bool, str]:
    path = Path(_TERM_ENABLE_FILE)
    try:
        if on:
            path.parent.mkdir(parents=True, exist_ok=True)
            tmp = path.with_name(path.name + ".tmp")
            with open(tmp, "w", encoding="utf-8") as f:
                f.write(f"Terminal switched on from the 44helper page by {ip} at "
                        f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
            os.chmod(tmp, 0o644)
            os.replace(tmp, path)
        else:
            try:
                path.unlink()
            except FileNotFoundError:
                pass
    except OSError as exc:
        return False, f"Could not switch the terminal {'on' if on else 'off'}: {exc}"
    log(f"Terminal switched {'ON' if on else 'OFF'} from the page by {ip}")
    return True, f"Terminal switched {'on' if on else 'off'}."

def _term_issue_ticket(session_token: str, tid: str) -> str:
    now = time.time()
    t = secrets.token_urlsafe(24)
    with _TERM_LOCK:
        for k in [k for k, v in _TERM_TICKETS.items() if v["exp"] < now]:
            del _TERM_TICKETS[k]
        _TERM_TICKETS[t] = {"sess": _session_key(session_token), "id": tid, "exp": now + _TERM_TICKET_TTL}
    return t

def _term_take_ticket(ticket: str, session_token: str) -> str | None:
    with _TERM_LOCK:
        v = _TERM_TICKETS.pop(ticket, None) if ticket else None
    if v is None or v["exp"] < time.time():
        return None
    if not hmac.compare_digest(v["sess"], _session_key(session_token)):
        return None
    return v["id"]

_WS_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
_WS_MAX = 1 << 16

class _WSProtocolError(Exception):
    def __init__(self, code: int, msg: str) -> None:
        super().__init__(msg)
        self.code = code

def _ws_accept_key(key: str) -> str:
    return base64.b64encode(hashlib.sha1((key + _WS_GUID).encode("ascii")).digest()).decode("ascii")

def _ws_frame(opcode: int, payload: bytes = b"") -> bytes:
    n = len(payload)
    b0 = 0x80 | opcode
    if n < 126:
        hdr = struct.pack("!BB", b0, n)
    elif n < 65536:
        hdr = struct.pack("!BBH", b0, 126, n)
    else:
        hdr = struct.pack("!BBQ", b0, 127, n)
    return hdr + payload

def _ws_close_frame(code: int, reason: str = "") -> bytes:
    return _ws_frame(0x8, struct.pack("!H", code) + reason.encode("utf-8")[:120])

class _WSReader:

    def __init__(self) -> None:
        self.buf = bytearray()
        self.frag_op: int | None = None
        self.frag = bytearray()

    def feed(self, data: bytes) -> list[tuple[int, bytes]]:
        self.buf += data
        out: list[tuple[int, bytes]] = []
        while len(self.buf) >= 2:
            b0, b1 = self.buf[0], self.buf[1]
            fin, rsv, op = b0 & 0x80, b0 & 0x70, b0 & 0x0F
            masked, n, i = b1 & 0x80, b1 & 0x7F, 2
            if rsv:
                raise _WSProtocolError(1002, "reserved bits set")
            if not masked:
                raise _WSProtocolError(1002, "client frames must be masked")
            if n == 126:
                if len(self.buf) < 4:
                    break
                n, i = struct.unpack_from("!H", self.buf, 2)[0], 4
            elif n == 127:
                if len(self.buf) < 10:
                    break
                n, i = struct.unpack_from("!Q", self.buf, 2)[0], 10
            if op >= 8 and (n > 125 or not fin):
                raise _WSProtocolError(1002, "bad control frame")
            if n > _WS_MAX:
                raise _WSProtocolError(1009, "message too big")
            if len(self.buf) < i + 4 + n:
                break
            mask = bytes(self.buf[i:i + 4])
            raw = bytes(self.buf[i + 4:i + 4 + n])
            del self.buf[:i + 4 + n]
            m = (mask * (n // 4 + 1))[:n]
            payload = (int.from_bytes(raw, "big") ^ int.from_bytes(m, "big")).to_bytes(n, "big")
            if op >= 8:
                if op not in (0x8, 0x9, 0xA):
                    raise _WSProtocolError(1002, "unknown control opcode")
                out.append((op, payload))
            elif op == 0:
                if self.frag_op is None:
                    raise _WSProtocolError(1002, "unexpected continuation frame")
                self.frag += payload
                if len(self.frag) > _WS_MAX:
                    raise _WSProtocolError(1009, "message too big")
                if fin:
                    out.append((self.frag_op, bytes(self.frag)))
                    self.frag_op, self.frag = None, bytearray()
            elif op in (1, 2):
                if self.frag_op is not None:
                    raise _WSProtocolError(1002, "new message inside a fragmented one")
                if fin:
                    out.append((op, payload))
                else:
                    self.frag_op, self.frag = op, bytearray(payload)
            else:
                raise _WSProtocolError(1002, "unknown opcode")
        return out

def _term_status(ip: str, headers) -> dict:
    enabled, why = _term_enabled()
    client_ok, cwhy = _term_client_ok(ip, headers)
    with _TERM_LOCK:
        busy = _TERM_ACTIVE.get("id") is not None
    cmds = {v["step"]: {"id": v["id"], "title": v["title"]} for v in _term_allowlist().values()}
    can_enable, ewhy = _term_can_enable(ip, headers)
    return {"enabled": enabled, "reason": why, "client_ok": client_ok, "client_reason": cwhy,
            "can_enable": can_enable, "enable_reason": ewhy,
            "busy": busy, "commands": cmds, "enable_file": str(_TERM_ENABLE_FILE)}

_TERM_ACTIVE: dict = {"id": None}
_TERM_IDLE_SEC = 600
_TERM_KILL_GRACE = 3.0

def _term_claim(tid: str) -> bool:
    with _TERM_LOCK:
        if _TERM_ACTIVE.get("id") is not None:
            return False
        _TERM_ACTIVE["id"] = tid
        return True

def _term_release() -> None:
    with _TERM_LOCK:
        _TERM_ACTIVE["id"] = None

def _term_set_size(fd: int, cols: int, rows: int) -> None:
    cols = max(2, min(500, int(cols)))
    rows = max(1, min(300, int(rows)))
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))

def _term_spawn(cmd: str) -> tuple[subprocess.Popen, int]:
    master, slave = os.openpty()
    _term_set_size(master, 80, 24)
    env = dict(os.environ, TERM="xterm-256color", COLORTERM="truecolor")
    env.setdefault("LANG", "C.UTF-8")
    argv = ["bash", "-c", cmd]
    setsid = shutil.which("setsid")
    try:
        if setsid:
            proc = subprocess.Popen([setsid, "-c"] + argv, stdin=slave, stdout=slave, stderr=slave,
                                    close_fds=True, env=env, cwd="/")
        else:
            proc = subprocess.Popen(argv, stdin=slave, stdout=slave, stderr=slave,
                                    close_fds=True, env=env, cwd="/", start_new_session=True)
    finally:
        os.close(slave)
    return proc, master

def _term_kill(proc: subprocess.Popen) -> None:
    if proc.poll() is not None:
        return
    for sig, wait in ((signal.SIGHUP, _TERM_KILL_GRACE), (signal.SIGKILL, 2.0)):
        try:
            os.killpg(proc.pid, sig)
        except (ProcessLookupError, PermissionError):
            try:
                proc.send_signal(sig)
            except ProcessLookupError:
                return
        try:
            proc.wait(timeout=wait)
            return
        except subprocess.TimeoutExpired:
            continue

def _term_session(sock, tid: str, alive: Callable[[], bool], ip: str) -> str:
    item = _term_allowlist().get(tid)
    if item is None:
        sock.sendall(_ws_close_frame(1008, "not allowed"))
        return "not on allow-list"
    proc, master = _term_spawn(item["cmd"])
    started = last_input = time.monotonic()
    log(f"Terminal opened: {item['title']} ({item['cmd']}) from {ip}")
    reader = _WSReader()
    reason = "?"

    def send_json(obj: dict) -> None:
        sock.sendall(_ws_frame(0x1, json.dumps(obj).encode("utf-8")))

    try:
        send_json({"t": "hello", "title": item["title"], "cmd": item["cmd"], "idle_sec": _TERM_IDLE_SEC})
        master_open = True
        while True:
            fds = [sock] + ([master] if master_open else [])
            r, _, _ = select.select(fds, [], [], 1.0)
            if master_open and master in r:
                try:
                    data = os.read(master, 65536)
                except OSError:
                    data = b""
                if data:
                    sock.sendall(_ws_frame(0x2, data))
                else:
                    master_open = False
            if sock in r:
                data = sock.recv(65536)
                if not data:
                    reason = "connection dropped"
                    break
                try:
                    msgs = reader.feed(data)
                except _WSProtocolError as exc:
                    sock.sendall(_ws_close_frame(exc.code, str(exc)))
                    reason = f"protocol error: {exc}"
                    break
                closing = False
                for op, payload in msgs:
                    if op == 0x8:
                        sock.sendall(_ws_close_frame(1000))
                        closing = True
                        break
                    if op == 0x9:
                        sock.sendall(_ws_frame(0xA, payload))
                    elif op == 0x2:
                        os.write(master, payload)
                        last_input = time.monotonic()
                    elif op == 0x1:
                        try:
                            msg = json.loads(payload.decode("utf-8"))
                        except (ValueError, UnicodeDecodeError):
                            continue
                        if msg.get("t") == "i" and isinstance(msg.get("d"), str):
                            os.write(master, msg["d"].encode("utf-8"))
                            last_input = time.monotonic()
                        elif msg.get("t") == "r":
                            try:
                                _term_set_size(master, msg.get("cols", 80), msg.get("rows", 24))
                            except (TypeError, ValueError, OSError):
                                pass
                if closing:
                    reason = "closed from the page"
                    break
            rc = proc.poll()
            if rc is not None and not master_open:
                send_json({"t": "exit", "code": rc})
                sock.sendall(_ws_close_frame(1000, "command finished"))
                reason = f"command finished (exit {rc})"
                break
            if rc is not None and master_open and not r:
                master_open = False
                continue
            if time.monotonic() - last_input > _TERM_IDLE_SEC:
                send_json({"t": "exit", "reason": "idle"})
                sock.sendall(_ws_close_frame(1000, "idle"))
                reason = f"idle {_TERM_IDLE_SEC // 60} minutes"
                break
            if not _term_enabled()[0]:
                send_json({"t": "exit", "reason": "switched_off"})
                sock.sendall(_ws_close_frame(1000, "switched off"))
                reason = "terminal switched off"
                break
            if not alive():
                send_json({"t": "exit", "reason": "logged_out"})
                sock.sendall(_ws_close_frame(4001, "logged out"))
                reason = "login ended"
                break
    except (BrokenPipeError, ConnectionResetError, OSError) as exc:
        reason = f"connection error: {exc}"
    finally:
        _term_kill(proc)
        try:
            os.close(master)
        except OSError:
            pass
        log(f"Terminal closed: {item['title']} from {ip} after {int(time.monotonic() - started)}s -- {reason}")
    return reason

def _cf_lookup_step(mode: str, distro: str, step_id: str) -> dict | None:
    for step in _CF_SCRIPTS.get(mode, {}).get(distro, []):
        if step["id"] == step_id:
            return step
    return None

def _dispatch_cf_action(payload: dict) -> dict:
    return _dispatch_tab_action(payload, _cf_lookup_step, "cf", valid_distros=("token", "quick"))

_QM_STATE_FILE = str(CONFIG_DIR / "44helper_quiet_state.json")
_QM_LOCK = threading.Lock()
_QM_STOP_TIMEOUT = 150
_QM_TIERS: list[tuple[str, list[str]]] = [
    ("watchdogs & timers", ["asl_dvs_watchdog*.timer", "asl_dvs_watchdog*.service", "monit.service",
                            "asl3-update-nodelist.timer", "asl3-update-astdb.timer", "man-db.timer"]),
    ("background disk users", ["pmie.service", "pmlogger.service", "pmproxy.service", "pmcd.service",
                               "packagekit.service", "man-db.service"]),
    ("suite web tools", ["*sysmon*.service", "nodecontrol.service", "*asl_dvs_dashboard*.service", "*asl-dvs-dashboard*.service",
                         "*instmon*.service", "*svx_dashboard*.service", "*m17*dashboard*.service",
                         "lighttpd.service"]),
    ("radio services", ["asterisk.service", "analog_bridge.service", "mmdvm_bridge.service",
                        "md380-emu.service", "svxlink.service", "svxlink-usrp.service",
                        "ircddbgateway*.service", "stfu.service"]),
]
_QM_NEVER = ["*44helper*", "*wifimon*", "ssh*", "sshd*", "cockpit*", "NetworkManager*", "firewalld*",
             "systemd-*", "dbus*", "wpa_supplicant*", "polkit*"]
_QM_LOCK_PATHS = ["/var/lib/dpkg/lock-frontend", "/var/lib/dpkg/lock",
                  "/var/lib/apt/lists/lock", "/var/cache/apt/archives/lock"]

def _qm_read_state() -> dict:
    try:
        with open(_QM_STATE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except (FileNotFoundError, ValueError, OSError):
        return {}

def _qm_write_state(state: dict) -> None:
    _compare_before_write(_QM_STATE_FILE, json.dumps(state, indent=1).encode("utf-8"))

def _qm_clear_state() -> None:
    try:
        os.remove(_QM_STATE_FILE)
    except FileNotFoundError:
        pass

def _qm_active_units() -> list[str]:
    try:
        r = subprocess.run(["systemctl", "list-units", "--all", "--plain", "--no-legend", "--no-pager",
                            "--type=service,timer", "--state=active"],
                           capture_output=True, text=True, timeout=20)
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return []
    units = []
    for line in (r.stdout or "").splitlines():
        parts = line.split()
        if parts and parts[0].endswith((".service", ".timer")):
            units.append(parts[0])
    return units

_QM_BOOTCHECK_TIMER = "asl_dvs_bootcheck.timer"
_QM_BOOTCHECK_SERVICE = "asl_dvs_bootcheck.service"

def _qm_bootcheck_units() -> list[str]:
    out = []
    try:
        r = subprocess.run(["systemctl", "show", "-p", "SubState", "--value", _QM_BOOTCHECK_TIMER],
                           capture_output=True, text=True, timeout=10)
        if r.stdout.strip() == "waiting":
            out.append(_QM_BOOTCHECK_TIMER)
        r = subprocess.run(["systemctl", "is-active", _QM_BOOTCHECK_SERVICE],
                           capture_output=True, text=True, timeout=10)
        if r.stdout.strip() in ("active", "activating"):
            out.append(_QM_BOOTCHECK_SERVICE)
    except (FileNotFoundError, subprocess.TimeoutExpired):
        pass
    return out

def _qm_resolve_plan(active: list[str] | None = None, bootcheck: list[str] | None = None) -> list[dict]:
    import fnmatch
    if active is None:
        active = _qm_active_units()
    if bootcheck is None:
        bootcheck = _qm_bootcheck_units()
    plan, seen = [], set()
    for tier, patterns in _QM_TIERS:
        for pat in patterns:
            for unit in sorted(active):
                if unit in seen or not fnmatch.fnmatchcase(unit.lower(), pat.lower()):
                    continue
                if any(fnmatch.fnmatchcase(unit.lower(), n.lower()) for n in _QM_NEVER):
                    continue
                seen.add(unit)
                plan.append({"unit": unit, "tier": tier})
        if tier == _QM_TIERS[0][0]:
            for unit in bootcheck:
                if unit not in seen:
                    seen.add(unit)
                    plan.append({"unit": unit, "tier": tier})
    return plan

def _qm_package_locks_busy() -> list[str]:
    import fcntl
    busy = []
    for path in _QM_LOCK_PATHS:
        try:
            fd = os.open(path, os.O_RDWR)
        except (FileNotFoundError, PermissionError, OSError):
            continue
        try:
            fcntl.lockf(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
            fcntl.lockf(fd, fcntl.LOCK_UN)
        except OSError:
            busy.append(path)
        finally:
            os.close(fd)
    return busy

_QM_TIER_NAMES = [t for t, _ in _QM_TIERS]
_QM_MANDB_AFTER = _QM_TIER_NAMES.index("background disk users")

def _qm_mandb_due(tier: str | None, done: bool) -> bool:
    return not done and (tier is None or _QM_TIER_NAMES.index(tier) > _QM_MANDB_AFTER)

def _qm_preview(plan: list[dict]) -> dict:
    stop, tier, killed = [], None, False
    for item in plan:
        if item["tier"] != tier:
            if _qm_mandb_due(item["tier"], killed):
                stop.append("sudo pkill -x mandb")
                killed = True
            tier = item["tier"]
            stop.append(f"# {tier}")
        stop.append(f"sudo systemctl stop {item['unit']}")
    if not killed:
        stop.append("sudo pkill -x mandb")
    restore = [f"sudo systemctl start {p['unit']}" for p in reversed(plan)]
    return {"stop": stop, "restore": restore}

def _qm_systemctl(verb: str, unit: str) -> tuple[bool, str]:
    argv = ["systemctl", verb, unit]
    if verb == "start" and unit == _QM_BOOTCHECK_SERVICE:
        argv = ["systemctl", "start", "--no-block", unit]
    try:
        r = subprocess.run(argv, capture_output=True, text=True, timeout=_QM_STOP_TIMEOUT)
        return r.returncode == 0, ((r.stdout or "") + (r.stderr or "")).strip()
    except subprocess.TimeoutExpired:
        return False, f"timed out after {_QM_STOP_TIMEOUT}s"
    except FileNotFoundError:
        return False, "systemctl not found"

_QM_CAUSE_HINTS = [
    (re.compile(r"address already in use|errno 98|port .* (in use|busy)", re.I),
     "Likely cause: something else is already using this service's network port -- often a second "
     "copy of the same tool (an older unit name) that started first."),
    (re.compile(r"no such file or directory|not found", re.I),
     "Likely cause: a file or program this service needs is missing -- was it removed or never installed?"),
    (re.compile(r"permission denied", re.I),
     "Likely cause: a permissions problem on one of this service's files."),
]

def _qm_failure_details(unit: str) -> list[str]:
    out = []
    try:
        st = subprocess.run(["systemctl", "status", unit, "--no-pager", "-n", "0", "-l"],
                            capture_output=True, text=True, timeout=15).stdout or ""
        jr = subprocess.run(["journalctl", "-u", unit, "-n", "15", "--no-pager", "-o", "cat"],
                            capture_output=True, text=True, timeout=15).stdout or ""
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return ["    (could not read this service's status or log)"]
    for ln in [l for l in st.splitlines() if l.strip()][:6]:
        out.append("    | " + ln.strip())
    if jr.strip():
        out.append(f"    --- last log lines for {unit} ---")
        out.extend("    | " + l for l in jr.splitlines()[-15:])
    for rx, hint in _QM_CAUSE_HINTS:
        if rx.search(st) or rx.search(jr):
            out.append("    " + hint)
            break
    return out

def _qm_restore_list(stopped: list[dict], lines: list[str]) -> list[str]:
    failed = []
    for item in reversed(stopped):
        ok, out = _qm_systemctl("start", item["unit"])
        lines.append(f"start {item['unit']}: {'ok' if ok else 'FAILED ' + out}")
        if not ok:
            failed.append(item["unit"])
            lines.extend(_qm_failure_details(item["unit"]))
    return failed

def _qm_on(reason: str = "manual") -> dict:
    if not _QM_LOCK.acquire(blocking=False):
        return {"success": False, "output": "A quiet-mode change is already in progress."}
    try:
        err = _require_root()
        if err:
            return err
        if _qm_read_state().get("active"):
            return {"success": False, "already_on": True, "output": "Quiet mode is already on."}
        busy = _qm_package_locks_busy()
        if busy:
            return {"success": False, "output": "A package job is running (locked: " + ", ".join(busy) +
                    "). Wait for it to finish, then try again."}
        plan = _qm_resolve_plan()
        state = {"active": True, "reason": reason, "started_at": time.time(), "stopped": [], "job_unit": None,
                 "boot_id": _bt_boot_id()}
        _qm_write_state(state)
        lines = [f"Quiet mode ON ({reason}) -- {len(plan)} unit(s) to pause."]
        tier, killed = None, False
        for item in plan:
            if item["tier"] != tier:
                if _qm_mandb_due(item["tier"], killed):
                    _qm_kill_mandb(lines)
                    killed = True
                tier = item["tier"]
                lines.append(f"# {tier}")
            ok, out = _qm_systemctl("stop", item["unit"])
            if not ok:
                lines.append(f"stop {item['unit']}: FAILED {out}")
                lines.append("Aborting -- restoring what was already paused.")
                failed = _qm_restore_list(state["stopped"], lines)
                _qm_clear_state()
                log(f"QUIET: on aborted at {item['unit']}; restore failures: {failed}")
                return {"success": False, "restore_ok": not failed, "output": "\n".join(lines)}
            lines.append(f"stop {item['unit']}: ok")
            state["stopped"].append(item)
            _qm_write_state(state)
        if not killed:
            _qm_kill_mandb(lines)
        log(f"QUIET: on ({reason}), paused {len(state['stopped'])} unit(s)")
        return {"success": True, "stopped": state["stopped"], "output": "\n".join(lines)}
    finally:
        _QM_LOCK.release()

def _qm_kill_mandb(lines: list[str]) -> None:
    try:
        r = subprocess.run(["pkill", "-x", "mandb"], capture_output=True, text=True, timeout=10)
        lines.append("pkill mandb: " + ("stopped a running index rebuild" if r.returncode == 0 else "none running"))
    except (FileNotFoundError, subprocess.TimeoutExpired):
        lines.append("pkill mandb: skipped")

def _qm_off(reason: str = "manual") -> dict:
    if not _QM_LOCK.acquire(blocking=False):
        return {"success": False, "output": "A quiet-mode change is already in progress."}
    try:
        err = _require_root()
        if err:
            return err
        state = _qm_read_state()
        if not state.get("active"):
            return {"success": True, "restore_ok": True, "output": "Quiet mode is not on -- nothing to restore."}
        lines = [f"Quiet mode OFF ({reason}) -- restoring {len(state.get('stopped', []))} unit(s) in reverse order."]
        failed = _qm_restore_list(state.get("stopped", []), lines)
        _qm_clear_state()
        if failed:
            lines.append("Some services did not come back: " + ", ".join(failed) +
                         ". A reboot is the simplest way to bring everything back.")
        log(f"QUIET: off ({reason}); restore failures: {failed}")
        return {"success": not failed, "restore_ok": not failed, "failed": failed, "output": "\n".join(lines)}
    finally:
        _QM_LOCK.release()

def _qm_status() -> dict:
    state = _qm_read_state()
    if state.get("active"):
        return {"active": True, "since": state.get("started_at"), "reason": state.get("reason"),
                "stopped": [p["unit"] for p in state.get("stopped", [])], "job_unit": state.get("job_unit"),
                "preview": _qm_preview(state.get("stopped", []))}
    plan = _qm_resolve_plan()
    return {"active": False, "plan": plan, "preview": _qm_preview(plan)}

def _qm_unit_running(unit: str) -> bool:
    try:
        r = subprocess.run(["systemctl", "show", unit, "-p", "SubState", "--value"],
                           capture_output=True, text=True, timeout=10)
        return (r.stdout or "").strip() == "running"
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return False

def _qm_startup_sweep() -> None:
    try:
        state = _qm_read_state()
        if not state.get("active"):
            return
        bid = state.get("boot_id")
        earlier = (bid != _bt_boot_id()) if bid else float(state.get("started_at") or 0) < _bt_btime()
        if earlier:
            _qm_clear_state()
            log("QUIET: quiet mode was left on before a reboot; the reboot already started everything again -- cleared")
            return
        job_unit = state.get("job_unit")
        if job_unit and _qm_unit_running(job_unit):
            log(f"QUIET: startup found quiet mode on with {job_unit} still running -- restoring after it finishes")

            def _wait_then_restore():
                while _qm_unit_running(job_unit):
                    time.sleep(10)
                log("QUIET: " + _qm_off("startup sweep, after package job").get("output", "").replace("\n", " | "))
            threading.Thread(target=_wait_then_restore, daemon=True).start()
            return
        log("QUIET: startup found quiet mode left on -- restoring in the background")

        def _restore_now():
            try:
                log("QUIET: " + _qm_off("startup sweep").get("output", "").replace("\n", " | "))
            except Exception as exc:
                log(f"QUIET: startup restore error: {exc}")
        threading.Thread(target=_restore_now, daemon=True).start()
    except Exception as exc:
        log(f"QUIET: startup sweep error (continuing startup): {exc}")

_QM_JOB_POLL_SEC = 2.0

def _qm_unit_props(unit: str) -> dict:
    try:
        r = subprocess.run(["systemctl", "show", unit, "-p", "ActiveState", "-p", "SubState",
                            "-p", "ExecMainStatus", "-p", "LoadState"],
                           capture_output=True, text=True, timeout=15)
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return {}
    props = {}
    for line in (r.stdout or "").splitlines():
        if "=" in line:
            k, v = line.split("=", 1)
            props[k.strip()] = v.strip()
    return props

def _qm_job_finish(job_key: str, success: bool, returncode) -> None:
    with _JOBS_LOCK:
        job = _JOBS.get(job_key)
        if job is not None:
            job.update(status="done", success=success, returncode=returncode, finished_at=time.time())
    _ev_notify()

_UNIT_JOB_PREFIX = "44helper-job-"
_UNIT_LIST_CACHE: dict = {"at": 0.0, "units": set()}

def _job_unit_name(job_key: str) -> str:
    return _UNIT_JOB_PREFIX + re.sub(r"[^A-Za-z0-9_.-]", "_", job_key)[:180]

def _unit_jobs_present() -> set:
    now = time.time()
    if now - _UNIT_LIST_CACHE["at"] < 5.0:
        return _UNIT_LIST_CACHE["units"]
    units = set()
    try:
        r = subprocess.run(["systemctl", "list-units", "--all", "--plain", "--no-legend", "--no-pager",
                            _UNIT_JOB_PREFIX + "*"], capture_output=True, text=True, timeout=15)
        for line in (r.stdout or "").splitlines():
            parts = line.split()
            if parts and parts[0].startswith(_UNIT_JOB_PREFIX):
                units.add(parts[0][:-8] if parts[0].endswith(".service") else parts[0])
    except (FileNotFoundError, subprocess.TimeoutExpired):
        pass
    _UNIT_LIST_CACHE.update(at=now, units=units)
    return units

def _follow_unit_to_end(job_key: str, unit: str, replay: bool = False,
                        sink: Callable[[str], None] | None = None) -> dict:
    argv = ["journalctl", "-f", "-o", "cat", "--no-pager", "-u", unit]
    if replay:
        argv[1:1] = ["-n", "all"]
    follower = subprocess.Popen(argv, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    fd, pending = follower.stdout.fileno(), [""]

    def _pump(wait: float) -> bool:
        ready, _, _ = select.select([fd], [], [], wait)
        if not ready:
            return False
        chunk = os.read(fd, 65536)
        if not chunk:
            return False
        text = pending[0] + chunk.decode("utf-8", "replace")
        lines = text.split("\n")
        pending[0] = lines.pop()
        for ln in lines:
            if not _DPKG_PROGRESS_RE.match(ln.rstrip("\r")):
                _job_append_output(job_key, ln + "\n")
                if sink is not None:
                    sink(ln + "\n")
        return True

    started, last_check, props = time.time(), 0.0, {}
    try:
        while True:
            _pump(1.0)
            if time.time() - last_check >= _QM_JOB_POLL_SEC:
                last_check = time.time()
                props = _qm_unit_props(unit)
                sub, act = props.get("SubState", ""), props.get("ActiveState", "")
                if act == "failed" or sub in ("exited", "failed") or \
                        (sub == "dead" and time.time() - started > 10):
                    break
        drain_until = time.time() + 2.0
        while time.time() < drain_until:
            _pump(0.3)
        if pending[0] and not _DPKG_PROGRESS_RE.match(pending[0]):
            _job_append_output(job_key, pending[0] + "\n")
            if sink is not None:
                sink(pending[0] + "\n")
    finally:
        follower.terminate()
        try:
            follower.wait(timeout=5)
        except subprocess.TimeoutExpired:
            follower.kill()
    return props

def _finish_unit(unit: str, props: dict) -> tuple[bool, int | None]:
    status = props.get("ExecMainStatus", "")
    rc = int(status) if status.lstrip("-").isdigit() else None
    ok = rc == 0 and props.get("ActiveState") != "failed"
    subprocess.run(["systemctl", "stop", unit], capture_output=True, timeout=30)
    subprocess.run(["systemctl", "reset-failed", unit], capture_output=True, timeout=30)
    _UNIT_LIST_CACHE["at"] = 0.0
    return ok, rc

_APT_NI_OPTS = "-o Dpkg::Options::=--force-confdef -o Dpkg::Options::=--force-confold"

def _run_pkg_unit(job_key: str, cmd: str) -> dict:
    gate = _pkg_health_gate(cmd)
    if gate:
        return {"success": False, "returncode": None, "output": gate.get("output", "")}
    unit = _job_unit_name(job_key)
    lines: list[str] = []
    try:
        adopting = unit in _unit_jobs_present() and _qm_unit_props(unit).get("SubState") == "running"
        if not adopting:
            subprocess.run(["systemctl", "stop", unit], capture_output=True, timeout=30)
            subprocess.run(["systemctl", "reset-failed", unit], capture_output=True, timeout=30)
            start = _run_argv(["systemd-run", f"--unit={unit}", "-p", "RemainAfterExit=yes",
                               "-p", "LogRateLimitIntervalSec=0",
                               "--setenv=DEBIAN_FRONTEND=noninteractive", "/bin/sh", "-c", cmd], timeout=30)
            if not start["success"]:
                return {"success": False, "returncode": None,
                        "output": "Could not start the package job: " + start["output"]}
            _UNIT_LIST_CACHE["at"] = 0.0
        props = _follow_unit_to_end(job_key, unit, replay=adopting, sink=lines.append)
        ok, rc = _finish_unit(unit, props)
    except Exception as exc:
        return {"success": False, "returncode": None, "output": "".join(lines) + f"Package job error: {exc}"}
    log(f"{'OK' if ok else 'FAIL'} (system-job, exit {rc}): {cmd}")
    return {"success": ok, "returncode": rc, "output": "".join(lines).strip()}

def _unit_job_worker(job_key: str, cmd: str, quiet: bool, low_priority: bool) -> None:
    own_quiet = False
    job_ok, rc = False, None
    unit = _job_unit_name(job_key)
    try:
        if quiet:
            if _qm_read_state().get("active"):
                _job_append_output(job_key, "=== Quiet mode is already on -- it will be left on after this job. ===\n")
            else:
                r = _qm_on("package job")
                _job_append_output(job_key, "=== Quiet mode: pausing node services ===\n" + r.get("output", "") + "\n")
                if not r.get("success"):
                    _job_append_output(job_key, "Quiet mode could not start -- the package job was NOT run.\n")
                    return
                own_quiet = True
            state = _qm_read_state()
            if state.get("active"):
                state["job_unit"] = unit
                _qm_write_state(state)
        subprocess.run(["systemctl", "stop", unit], capture_output=True, timeout=30)
        subprocess.run(["systemctl", "reset-failed", unit], capture_output=True, timeout=30)
        props_argv = ["-p", "RemainAfterExit=yes", "-p", "LogRateLimitIntervalSec=0"]
        if low_priority:
            props_argv += ["-p", "Nice=19", "-p", "IOSchedulingClass=best-effort", "-p", "IOSchedulingPriority=7"]
        start = _run_argv(["systemd-run", f"--unit={unit}"] + props_argv +
                          ["--setenv=DEBIAN_FRONTEND=noninteractive", "/bin/sh", "-c", cmd], timeout=30)
        if not start["success"]:
            _job_append_output(job_key, "Could not start the package job: " + start["output"] + "\n")
            return
        _UNIT_LIST_CACHE["at"] = 0.0
        _job_append_output(job_key, f"=== Running as its own system job ({unit})"
                                    + (", low priority" if low_priority else "")
                                    + " -- keeps going even if you log out or the helper restarts ===\n")
        props = _follow_unit_to_end(job_key, unit)
        job_ok, rc = _finish_unit(unit, props)
        _job_append_output(job_key, f"=== Package job finished: {'OK' if job_ok else 'FAILED'} (exit {rc}) ===\n")
        state = _qm_read_state()
        if state.get("active") and state.get("job_unit") == unit:
            state["job_unit"] = None
            _qm_write_state(state)
    except Exception as exc:
        _job_append_output(job_key, f"Package job error: {exc}\n")
    finally:
        if own_quiet:
            r = _qm_off("package job finished")
            _job_append_output(job_key, "=== Quiet mode: restoring node services ===\n" + r.get("output", "") + "\n")
            if not r.get("restore_ok", True):
                _job_append_output(job_key, "WARNING: not every service came back -- a reboot is recommended.\n")
        _qm_job_finish(job_key, job_ok, rc)
        log(f"{'OK' if job_ok else 'FAIL'} (system-job, exit {rc}): {cmd}")

def _start_unit_job(job_key: str, cmd: str, quiet: bool = False, low_priority: bool = False) -> dict:
    unit = _job_unit_name(job_key)
    with _JOBS_LOCK:
        existing = _JOBS.get(job_key)
        if existing is not None and existing["status"] == "running":
            return {"job_key": job_key, "status": "running"}
    if unit in _unit_jobs_present() and _qm_unit_props(unit).get("SubState") == "running":
        _adopt_unit_job(job_key, unit)
        return {"job_key": job_key, "status": "running", "attached": True}
    with _JOBS_LOCK:
        _JOBS[job_key] = {"status": "running", "output": "", "success": None,
                          "returncode": None, "started_at": time.time(), "cmd": cmd}
    log(f"RUN(system job{', quiet' if quiet else ''}): {cmd}")
    threading.Thread(target=_unit_job_worker, args=(job_key, cmd, quiet, low_priority), daemon=True).start()
    return {"job_key": job_key, "status": "running"}

def _adopt_unit_job(job_key: str, unit: str) -> None:
    with _JOBS_LOCK:
        if job_key in _JOBS and _JOBS[job_key]["status"] == "running":
            return
        started = time.time()
        _JOBS[job_key] = {"status": "running", "success": None, "returncode": None, "started_at": started,
                          "cmd": "(re-attached)", "output": f"=== Re-attached to {unit} after a helper "
                                                            "restart -- output so far: ===\n"}

    def _run():
        job_ok, rc = False, None
        try:
            p = _follow_unit_to_end(job_key, unit, replay=True)
            job_ok, rc = _finish_unit(unit, p)
            _job_append_output(job_key, f"=== Package job finished: {'OK' if job_ok else 'FAILED'} (exit {rc}) ===\n")
        except Exception as exc:
            _job_append_output(job_key, f"Re-attach error: {exc}\n")
        finally:
            _qm_job_finish(job_key, job_ok, rc)
    log(f"Re-attached to running system job {unit}")
    threading.Thread(target=_run, daemon=True).start()

def _start_quiet_apt_job(job_key: str, cmd: str) -> dict:
    return _start_unit_job(job_key, cmd, quiet=True, low_priority=True)

def _repair_cmd() -> str:
    return (
        "echo '=== 1/4 finishing interrupted installs ==='; "
        "sudo DEBIAN_FRONTEND=noninteractive dpkg --force-confdef --force-confold --configure -a; "
        "echo '=== 2/4 finishing half-installed packages ==='; ( " + _RECOVER_CONFIGURE_CMD + " ); "
        "echo '=== 3/4 re-installing broken packages ==='; ( " + _RECOVER_REINSTALL_CMD + " ); "
        "echo '=== 4/4 final pass ==='; sudo DEBIAN_FRONTEND=noninteractive dpkg --force-confdef --force-confold --configure -a; "
        "a=$(dpkg --audit 2>&1); if [ -n \"$a\" ]; then echo \"$a\"; "
        "echo 'Still broken after the repair -- the purge will NOT be started.'; exit 1; fi; "
        "echo 'Package system is healthy.'"
    )

def _dispatch_repair_action(payload: dict) -> dict:
    if payload.get("action") != "start":
        return {"success": False, "output": "Unknown repair action."}
    if payload.get("confirm") is not True:
        return {"success": False, "output": "The repair needs confirm:true."}
    err = _require_root()
    if err:
        return err
    fix = _guard_autofix("update")
    if fix["still_masked"]:
        return {"success": False, "output": "Masked services could not be cleared: " + ", ".join(fix["still_masked"])}
    return _start_quiet_apt_job("repair_packages", _repair_cmd())

def _dispatch_quiet_action(payload: dict) -> dict:
    action = str(payload.get("action", ""))
    if action == "on":
        return _qm_on("manual")
    if action == "off":
        return _qm_off("manual")
    if action == "reboot":
        if payload.get("confirm") is not True:
            return {"success": False, "output": "Reboot requires confirm:true."}
        err = _require_root()
        if err:
            return err
        unit = f"44helper-reboot-{int(time.time())}"
        r = _run_argv(["systemd-run", "--on-active=3", f"--unit={unit}", "/bin/systemctl", "reboot"], timeout=20)
        r["output"] = ("Reboot scheduled in 3 seconds." if r["success"] else "Could not schedule reboot: " + r["output"])
        return r
    return {"success": False, "output": f"Unknown quiet-mode action: {action}"}

_RECOVER_CHECK_CMD = (
    "echo '--- package jobs running right now:'; pgrep -a 'apt|dpkg|unattended-upgr' || echo '(none)'; "
    "echo '--- dpkg --audit:'; a=$(dpkg --audit 2>&1); "
    "if [ -z \"$a\" ]; then echo 'Nothing listed -- the package system is healthy.'; "
    "else echo \"$a\"; echo; echo 'Problems listed above. Do NOT reboot until they are fixed: run step 10, "
    "then step 11 if anything is marked for reinstall, then this check again.'; fi; true"
)
_RECOVER_NICE = "nice -n 19 ionice -c2 -n7"
_RECOVER_HEAVY = "^(linux-(image|headers|base|kbuild)|raspi-firmware|raspberrypi-kernel|initramfs-tools)"
_RECOVER_MASK_HINT = ("_MASKHINT='If a line above says \"is masked\": that service is blocked from starting and its "
                      "package cannot finish. Clear it with: sudo systemctl unmask <name>.service -- then run this "
                      "step again. (Masks on this helper'\"'\"'s own install-tab services are cleared automatically.)'; ")
_RECOVER_CONFIGURE_CMD = (
    _RECOVER_MASK_HINT +
    "pk=$(dpkg-query -W -f='${db:Status-Abbrev} ${binary:Package}\\n' 2>/dev/null | "
    "awk 'substr($1,2,1) ~ /[UFWt]/ {print $2}'); "
    "if [ -z \"$pk\" ]; then echo 'No half-installed packages.'; else "
    f"light=$(echo \"$pk\" | grep -vE '{_RECOVER_HEAVY}'); heavy=$(echo \"$pk\" | grep -E '{_RECOVER_HEAVY}'); "
    "if [ -n \"$light\" ]; then echo '=== finishing ordinary packages (one command -- dpkg sorts the order) ==='; "
    f"sudo {_RECOVER_NICE} dpkg --force-confdef --force-confold --configure $light || "
    "{ echo 'Finishing the ordinary packages failed -- stopping here. Copy this output.'; echo \"$_MASKHINT\"; exit 1; }; fi; "
    "if [ -n \"$heavy\" ]; then echo '=== finishing kernel/firmware packages (last, one command) ==='; "
    f"sudo {_RECOVER_NICE} dpkg --force-confdef --force-confold --configure $heavy || "
    "{ echo 'Finishing the kernel/firmware packages failed -- stopping here. Copy this output.'; echo \"$_MASKHINT\"; exit 1; }; fi; fi; "
    "echo '=== pending finishing jobs ==='; "
    f"sudo {_RECOVER_NICE} dpkg --force-confdef --force-confold --configure --pending || exit 1; "
    "a=$(dpkg --audit 2>&1); if [ -n \"$a\" ]; then echo \"$a\"; "
    "echo 'Still listed above -- if any say reinstall, run step 11.'; exit 1; fi; "
    "echo 'dpkg --audit is clean.'"
)
_RECOVER_REINSTALL_CMD = (
    "pk=$( { dpkg-query -W -f='${db:Status-Abbrev} ${binary:Package}\\n' 2>/dev/null | "
    "awk 'substr($1,3,1)==\"R\" {print $2}'; "
    "dpkg --audit 2>/dev/null | awk '/missing the (list|md5sums) control file/ {f=1; next} "
    "/^ *$/ {f=0} f && /^ [^ ]/ {print $1}'; } | sed 's/:.*//' | sort -u); "
    "if [ -z \"$pk\" ]; then echo 'No packages need a reinstall.'; exit 0; fi; rc=0; "
    "for n in $pk; do "
    "deb=$(ls -t /var/cache/apt/archives/${n}_*.deb 2>/dev/null | head -n1); "
    "if [ -z \"$deb\" ]; then echo \"=== no copy of $n on the Pi -- downloading it ===\"; "
    "mkdir -p /tmp/44helper-debs && cd /tmp/44helper-debs && apt-get download \"$n\" >/dev/null 2>&1; "
    "deb=$(ls -t /tmp/44helper-debs/${n}_*.deb 2>/dev/null | head -n1); cd /; fi; "
    "if [ -n \"$deb\" ]; then echo \"=== re-installing $n from $deb ===\"; "
    f"sudo {_RECOVER_NICE} dpkg -i \"$deb\" || rc=1; "
    "else echo \"$n: could not download a copy (no internet, or not in any package source). "
    "Fix the network or sources, then run this step again.\"; rc=1; fi; done; exit $rc"
)
