_TERM_ASSETS: dict[str, tuple[str, bytes]] = {}

def _term_asset(name: str) -> tuple[str, bytes] | None:
    if name not in _TERM_ASSETS_B64:
        return None
    if name not in _TERM_ASSETS:
        ctype, sha, b64 = _TERM_ASSETS_B64[name]
        raw = gzip.decompress(base64.b64decode("".join(b64.split())))
        if hashlib.sha256(raw).hexdigest() != sha:
            log(f"Terminal: embedded {name} failed its checksum -- not served")
            return None
        _TERM_ASSETS[name] = (ctype + "; charset=utf-8", raw)
    return _TERM_ASSETS[name]

_cfg: configparser.ConfigParser

def main() -> None:
    global _cfg
    _cfg = load_config()

    host = _cfg.get("server", "host", fallback="0.0.0.0")
    port = _cfg.getint("server", "port", fallback=9997)

    log(f"{APP_HEADER} v{APP_VERSION} ({APP_STAGE}) starting on {host}:{port}")
    log("Serving plaintext HTTP only (no built-in TLS). Keep this on a "
        "trusted LAN/VPN, or put a TLS-terminating reverse proxy in front "
        "of it if reachable from anywhere less trusted.")
    if os.geteuid() != 0:
        log("WARNING: Not running as root -- installs, purges, firewall "
            "changes, and router SSH actions will likely fail with permission errors, "
            "and root-password login will always fail (/etc/shadow won't be readable).")

    _qm_startup_sweep()
    _sessions_load()
    threading.Thread(target=_bt_snapshot_loop, name="boot-snapshot", daemon=True).start()

    server = _QuietThreadingHTTPServer((host, port), Handler)

    def _sigterm(signum, frame):
        log("SIGTERM received, shutting down")
        threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, _sigterm)

    global _HB_HTTP_OK_AT
    probe_host, probe_port = server.server_address[0], server.server_address[1]
    if probe_host in ("0.0.0.0", ""):
        probe_host = "127.0.0.1"
    _HB_HTTP_OK_AT = time.monotonic()
    threading.Thread(target=_hb_probe_loop, args=(probe_host, probe_port), name="health-probe", daemon=True).start()
    threading.Thread(target=_hb_loop, name="sd-heartbeat", daemon=True).start()
    _sd_notify("READY=1")

    try:
        server.serve_forever()
    except KeyboardInterrupt:
        log("KeyboardInterrupt, shutting down")
        server.shutdown()

if __name__ == "__main__":
    parser = argparse.ArgumentParser(
        description=f"{APP_TITLE} — 44Net Connect / firewall / router dashboard"
    )
    parser.add_argument("--install", action="store_true", help="Install as a systemd service & start")
    parser.add_argument("--uninstall", action="store_true", help="Stop & remove the systemd service")
    parser.add_argument("--boot-report", action="store_true", help="Print the Boot tab's report (with --json: as JSON) and exit")
    parser.add_argument("--json", action="store_true", help="With --boot-report: print JSON")
    args = parser.parse_args()

    if args.boot_report:
        _out, sys.stdout = sys.stdout, sys.stderr
        try:
            _cfg = load_config()
            _rep = json.dumps(build_boot_report("json"), indent=1) + "\n" if args.json else build_boot_report()["text"]
        finally:
            sys.stdout = _out
        sys.stdout.write(_rep)
    elif args.install:
        install_service()
    elif args.uninstall:
        uninstall_service()
    else:
        main()
